/**
 * `range-pressure`: the "HEATMAP" of KENJI, ported to the study contract. It is **not** a heatmap and knows nothing about depth: it is a
 * multi-window stochastic that colours the candles.
 *
 * For each bar, for `i` = 1..`plotNumber` a window of `i * inc` bars gives one stochastic — `(close - ll) / (hh - ll) * 100`, `hh`/`ll` the
 * window's high and low, 50 when the window is flat — smoothed by an EMA whose length is `smooth` (or `smooth + i` with Waves on) and kept
 * per window between bars; the bar's value is the mean of the `plotNumber` smoothed values. The state is the one `getColour` reads:
 * ≥80 overbought, ≥70 pre-overbought, ≤20 oversold, ≤30 pre-sold, else neutral.
 *
 * Pine: `KENJI` `getColour` (`:786-796`), the loop (`:790-830`) and the inputs of `group_PRESSURE` (`origin/main` `faaac98`, `:763-777`). The barcolor call (`:2781`) is presentation:
 * whether a candle is painted only on the extremes is the renderer's decision, so this piece returns the value and the state of every bar
 * and a `bgcolor` over the bar's slot for the painter; it never paints.
 */
import type { InputSpec, InputValues } from '../engine/inputs/schema.ts';
import { readInputs } from '../engine/inputs/schema.ts';
import type { Plot, StudyDef, StudyOutput } from '../engine/studies/contract.ts';
import type { Bar } from '../engine/series/source.ts';
import { CYCLE_SESSIONS, type CycleSessionSpec } from './cycle-90.ts';
import { offsetMs } from '../app/traded/sessions.ts';

/** A number input as the Pine falls back when the value is not one. */
const num = (values: InputValues, id: string, fallback: number): number => { const v = values[id]; return typeof v === 'number' && Number.isFinite(v) ? v : fallback; };
/** A boolean input. */
const bool = (values: InputValues, id: string, fallback: boolean): boolean => { const v = values[id]; return typeof v === 'boolean' ? v : fallback; };

/** The colour a state has in the palette of the study, as the Pine's four colours and grey. */
export type RangePressureState = 'overbought' | 'preOverbought' | 'neutral' | 'preSold' | 'oversold';
export interface RangePressureRow { readonly value: number; readonly state: RangePressureState }

export const INPUTS: readonly InputSpec[] = [
  { id: 'inc', kind: 'int', name: 'Increment', default: 10, min: 1, max: 20, group: 'Range pressure' },
  { id: 'smooth', kind: 'int', name: 'Smooth', default: 2, min: 1, max: 10, group: 'Range pressure' },
  { id: 'plotNumber', kind: 'int', name: 'Windows', default: 21, min: 1, max: 28, group: 'Range pressure' },
  // Waves: each window's EMA is one bar longer than the one before it (`smooth + i`), as `IncType` in the Pine (`:769`, `:802`). The Pine ships it
  // **on** (`KENJI:766`); the port had it off (T-1223).
  { id: 'waves', kind: 'bool', name: 'Waves', default: true, group: 'Range pressure' },
  // `pressure_alert` is **commented out** in the Pine (`//pressure_alert = …`, and its two `alert` calls with it), so the input is retired here
  // instead of kept as an idle switch (T-1235). The cross conditions still travel in the readout (`rp:cross`).
  // `cycle_filter` (`KENJI:784`, default on): only the band of the side's own 90-minute window is shaded.
  { id: 'cycleFilter', kind: 'bool', name: 'Filter', default: true, group: 'Range pressure' },
  // The four state colours (`KENJI:770-773`), each drawn at 30 % (`color.new(x, 70)`): they are the inputs the piece lacked.
  { id: 'preSoldColor', kind: 'color', name: 'Sold: pre', default: '#179cef', group: 'Range pressure style' },
  { id: 'soldColor', kind: 'color', name: 'Sold: over', default: '#02269e', group: 'Range pressure style' },
  { id: 'preOverboughtColor', kind: 'color', name: 'Overbought: pre', default: '#b96f02', group: 'Range pressure style' },
  { id: 'overboughtColor', kind: 'color', name: 'Overbought: over', default: '#cf0000', group: 'Range pressure style' },
  // The volume peak (`KENJI:777-782`, formula at `:842-846` and its colour at `:2448`).
  { id: 'peak', kind: 'bool', name: 'Peak', default: true, group: 'Volume peak' },
  { id: 'peakBullColor', kind: 'color', name: 'Peak bull', default: '#179cef', group: 'Volume peak' },
  { id: 'peakBearColor', kind: 'color', name: 'Peak bear', default: '#cf0000', group: 'Volume peak' },
  // `volume_peak_mult` and `volume_peak_len` are **not** inputs: the Pine clamps them inside the calculation, `ta.sma(volume[1], 72)` and
  // `2.0 * ta.stdev(volume[1], 72)` (`KENJI:844-845`, `origin/main` `faaac98`). A layout saved while they existed keeps its keys and they are
  // ignored on load and never exported again: this is a retirement, not a forgotten input (T-1223 bis).
  // The Pine's peak alert (`:782`, fired at `:2455`): declared, as every alert of this product is, and read by the readout.
  { id: 'peakAlert', kind: 'bool', name: 'Peak alert', default: true, group: 'Volume peak' },
];

/** The state of one value, by the Pine's thresholds (`getColour`, `:776-786`); a value exactly on a threshold takes the stricter state. */
export function stateOf(value: number): RangePressureState {
  if (value >= 80) return 'overbought';
  if (value >= 70) return 'preOverbought';
  if (value <= 20) return 'oversold';
  if (value <= 30) return 'preSold';
  return 'neutral';
}

/** The colour each state is painted with, from the four Pine inputs (`pre_bull` #179cef, `final_bull` #02269e, `pre_bear` #b96f02, `final_bear` #cf0000). */
export const COLOURS: Readonly<Record<RangePressureState, string>> = {
  overbought: '#cf0000', preOverbought: '#b96f02', neutral: 'rgba(128,128,128,0)', preSold: '#179cef', oversold: '#02269e',
};

/** The defaults above as a table, for a caller that has no inputs (tests and older callers). */
const colour = (values: InputValues, id: string, fallback: string): string => {
  const v = values[id];
  return typeof v === 'string' && /^#[0-9a-f]{6}$/i.test(v) ? v : fallback;
};

/** The four state colours a run paints with: the inputs when they are there, the defaults otherwise (`getColour`, `KENJI:787-797`). */
export function coloursOf(values: InputValues): Readonly<Record<RangePressureState, string>> {
  return {
    overbought: colour(values, 'overboughtColor', COLOURS.overbought),
    preOverbought: colour(values, 'preOverboughtColor', COLOURS.preOverbought),
    neutral: COLOURS.neutral,
    preSold: colour(values, 'preSoldColor', COLOURS.preSold),
    oversold: colour(values, 'soldColor', COLOURS.oversold),
  };
}

/** The peak's own numbers, clamped as the Pine clamps them (`KENJI:844-846`, `origin/main`): 72 bars of baseline, two deviations. Not inputs. */
export const PEAK_BASELINE = 72;
export const PEAK_SENSITIVITY = 2;

/**
 * The bars the Pine marks as a volume peak (`KENJI:842-846`): the bar's volume is over the mean of the `len` bars **before** it plus `mult`
 * deviations of those same bars — the bar never raises its own threshold — and only from bar 12 on, as `bar_index >= 12` says.
 */
export function volumePeaks(bars: readonly Bar[], len: number, mult: number): boolean[] {
  const out: boolean[] = [];
  const n = Math.max(1, Math.round(len));
  for (let i = 0; i < bars.length; i++) {
    const bar = bars[i]!;
    if (i < 12 || i < n) { out.push(false); continue; }
    const slice = bars.slice(i - n, i).map(b => b[5] ?? 0);
    const mean = slice.reduce((a, b) => a + b, 0) / n;
    const sd = Math.sqrt(slice.reduce((a, b) => a + (b - mean) ** 2, 0) / n);
    out.push((bar[5] ?? 0) > mean + mult * sd);
  }
  return out;
}

/**
 * The value and the state of every bar, in the bars' order. The EMAs are kept per window as the Pine keeps them in `emaHist`, so the result
 * for a bar depends on the bars before it and on nothing else. Pure: no canvas, no store, no network.
 */
export function rangePressure(bars: readonly Bar[], values: InputValues): RangePressureRow[] {
  const inc = Math.max(1, Math.round(num(values, 'inc', 10))), smooth = Math.max(1, Math.round(num(values, 'smooth', 2)));
  const windows = Math.min(28, Math.max(1, Math.round(num(values, 'plotNumber', 21)))), waves = bool(values, 'waves', false);
  const ema = new Array<number | null>(windows + 1).fill(null), out: RangePressureRow[] = [];
  for (let n = 0; n < bars.length; n++) {
    let sum = 0;
    for (let i = 1; i <= windows; i++) {
      const c = i * inc;
      // The Pine sets `hh = high` and then loops `for k = 0 to c - 1` over `high[k]`/`low[k]` (inclusive), so the window is this bar
      // plus the c - 1 before it: the current bar is already in hh/ll, so the loop starts at the bar before it.
      //
      // With the lookback **incomplete** the Pine does not compute with what it has (T-1118, measured against the original with the oracle that lives outside the repo):
      // `high[k]`/`low[k]` past the series are `na`, so `hh`/`ll` are `na` and `getColour`'s guard falls to **50** — and the EMA seeds
      // from that 50 and carries it (`KENJI:790-830`). Replicating it is what turned 224 disagreements into 0.
      const close = bars[n]![4]!;
      let stoch = 50;
      if (n >= c - 1) {
        let hh = bars[n]![2]!, ll = bars[n]![3]!;
        for (let k = 1; k < c; k++) {
          const bar = bars[n - k]!;
          hh = Math.max(hh, bar[2]!); ll = Math.min(ll, bar[3]!);
        }
        stoch = hh !== ll ? (close - ll) / (hh - ll) * 100 : 50;
      }
      const alpha = 2 / ((waves ? smooth + i : smooth) + 1), previous = ema[i];
      const next = previous === null || previous === undefined ? stoch : stoch * alpha + previous * (1 - alpha);
      ema[i] = next;
      sum += next;
    }
    const value = sum / windows;
    out.push({ value, state: stateOf(value) });
  }
  return out;
}

/**
 * Which side crossed at each bar, if either: the Pine's two `alertcondition`s (`KENJI:2783-2786`) and the only thing its `bgcolor` paints
 * (`:2778`, `:2781`) — `crossover(value, 90)` up, `crossunder(value, 10)` down. Every other bar is `null`, however high or low its value is.
 */
export type RangePressureCross = 'over' | 'under';
export function crossOf(rows: readonly RangePressureRow[]): (RangePressureCross | null)[] {
  return rows.map((row, i) => {
    const before = rows[i - 1]?.value;
    if (before === undefined) return null;
    if (before < 90 && row.value >= 90) return 'over';
    if (before > 10 && row.value <= 10) return 'under';
    return null;
  });
}

/**
 * The bars of the view, as the painter's `bgcolor`: **every bar whose state is not neutral**, in that state's colour (T-1219). This is a
 * **declared deviation** from the Pine, which colours only the bar where the 90/10 condition turns true (`heatmap_short_trigger`/`_long_trigger`,
 * `_Bool_TRUE(x) = x and not x[1]`, `KENJI:838-839`, painted at `:2363-2366`). Measured on 1500 hourly bars, the cross alone paints 36 bars
 * (2.4 %), and many views hold none at all: the piece was on and looked off, which is what the person reported. The cross is still computed and
 * published in the readout (`rp:cross`), which is where the Pine uses it for its alerts; what changes is only what is shaded.
 */
/**
 * The 90-minute windows of each side, **imported from `cycle-90`** and not written again (T-1235): the four bull ones are A and M and the four bear
 * ones D and X, exactly as `Bookmap.Cycle90_Window()` gives them (`Kenji-library:32-38`), the same hours `OddEyeCircle` keeps. The zone is New York
 * and it is not the page's: `offsetMs` reads the wall clock there, so the page's own zone only changes how an hour is written, never where it falls.
 */
export const BULL_WINDOWS: readonly CycleSessionSpec[] = CYCLE_SESSIONS.filter(session => session.variant === 'A' || session.variant === 'M');
export const BEAR_WINDOWS: readonly CycleSessionSpec[] = CYCLE_SESSIONS.filter(session => session.variant === 'D' || session.variant === 'X');
const CYCLE_ZONE = 'America/New_York';

/** Whether `t` falls inside one of those windows, in New York wall-clock minutes (`KENJI:2665-2668`). */
export function inCycleWindow(t: number, windows: readonly CycleSessionSpec[]): boolean {
  const minutes = Math.floor((t + offsetMs(CYCLE_ZONE, t)) / 60_000) % 1440;
  return windows.some(window => window.startMin <= minutes && minutes < window.endMin);
}

/** The Pine's gate (`KENJI:2668`): the side decides which window must hold the bar; a neutral bar is never filtered. */
export function cycleBandOk(t: number, state: RangePressureState, filter: boolean): boolean {
  if (!filter) return true;
  if (state === 'overbought' || state === 'preOverbought') return inCycleWindow(t, BEAR_WINDOWS);
  if (state === 'oversold' || state === 'preSold') return inCycleWindow(t, BULL_WINDOWS);
  return true;
}

export interface PaintInputs {
  /** The four state colours; the defaults when absent (`coloursOf`). */
  colours?: Readonly<Record<RangePressureState, string>>;
  /** The bars the Pine marks as a volume peak, and the two colours it gives them (`KENJI:2448`). */
  peaks?: readonly boolean[];
  /** `cycle_filter` (`KENJI:784`): off, every bar of a side is shaded, whatever window it is in. */
  cycleFilter?: boolean;
  peakBullColor?: string;
  peakBearColor?: string;
}

/**
 * How opaque each shade is, as the Pine's own `color.new(x, transparency)` numbers say (`origin/main` `faaac98`, `KENJI:768-776`): the two "pre"
 * colours at 95 (5 %), the two final ones at 90 (10 %) — the Pine's comment still claims «30 % por defecto», the numbers are what is drawn — and
 * the two volume-peak colours at 70 (30 %), which did not change.
 */
const ALPHA: Readonly<Record<RangePressureState, number>> = { overbought: 0.1, preOverbought: 0.05, neutral: 0, preSold: 0.05, oversold: 0.1 };
const PEAK_ALPHA = 0.3;

export function plotsOf(bars: readonly Bar[], barMs: number, rows: readonly RangePressureRow[], inputs: PaintInputs = {}): Plot[] {
  const plots: Plot[] = [], colours = inputs.colours ?? COLOURS;
  for (let i = 0; i < bars.length; i++) {
    const row = rows[i], bar = bars[i];
    if (!row || !bar) continue;
    // A volume peak takes the colour of the side it happened on, but only when it falls inside range pressure (≤30 low, ≥70 high), which is the
    // Pine's own condition: `getAverage >= 70 ? bear : getAverage <= 30 ? bull : na` (`KENJI:2448`, drawn when `not na(rangePressureBg)` at `:2449`).
    const cycleOk = cycleBandOk(bar[0]!, row.state, inputs.cycleFilter !== false);
    if (inputs.peaks?.[i] === true) {
      const side = row.state === 'overbought' || row.state === 'preOverbought' ? 'bear' : row.state === 'oversold' || row.state === 'preSold' ? 'bull' : null;
      if (side) {
        // The peak inherits the same filter (`KENJI:2679`, `volumePeakInRange … and cycleBandOk`).
        if (cycleOk) {
          const peakColor = side === 'bear' ? (inputs.peakBearColor ?? '#cf0000') : (inputs.peakBullColor ?? '#179cef');
          plots.push({ kind: 'bgcolor', t0: bar[0]!, t1: bar[0]! + barMs, color: peakColor, alpha: PEAK_ALPHA });
          continue;
        }
      }
    }
    if (row.state !== 'neutral' && cycleOk) plots.push({ kind: 'bgcolor', t0: bar[0]!, t1: bar[0]! + barMs, color: colours[row.state], alpha: ALPHA[row.state] });
  }
  return plots;
}

/** The inputs of the piece, as the registry reads them. */
export const RANGE_PRESSURE: StudyDef = {
  api: 1,
  id: 'range-pressure',
  name: 'Pressure',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx) {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 2) return null;
    const bars = series.bars, barMs = bars.length > 1 ? Math.abs(bars[1]![0]! - bars[0]![0]!) : ctx.zoneBarMs;
    const values = readInputs(INPUTS, ctx.params);
    const rows = rangePressure(bars, values), crosses = crossOf(rows);
    // The volume peak: its own switch, its sensitivity and its baseline (`KENJI:842-846`), silent when the switch is off.
    // The peak's baseline and sensitivity are the Pine's own numbers, not inputs (T-1223 bis): `ta.sma(volume[1], 72)`, `2.0 * ta.stdev(...)`.
    const peaks = bool(values, 'peak', true) ? volumePeaks(bars, PEAK_BASELINE, PEAK_SENSITIVITY) : [];
    const plots = plotsOf(bars, barMs, rows, {
      colours: coloursOf(values), peaks, cycleFilter: bool(values, 'cycleFilter', true),
      peakBullColor: colour(values, 'peakBullColor', '#179cef'), peakBearColor: colour(values, 'peakBearColor', '#cf0000'),
    });
    // What a panel may read (D-31). One row, not one a bar: `plotsOf` already carries a bar's state as its colour, and a row per bar would
    // double the frame's objects for the same numbers. The last completed bar is what a panel shows; a per-bar readout would need a typed
    // array in the contract and a measurement, not a copy of the plots.
    const last = rows[rows.length - 1];
    const counts = rows.reduce<Record<string, number>>((tally, row) => {
      tally[row.state] = (tally[row.state] ?? 0) + 1;
      return tally;
    }, {});
    const readout = [
      {
        id: 'rp:last',
        label: 'last bar',
        values: last ? [{ id: 'state', value: last.state }, { id: 'value', value: last.value }] : [],
      },
      { id: 'rp:window', label: 'window', values: Object.entries(counts).map(([state, count]) => ({ id: state, value: count })) },
      // The Pine's two alerts, as the condition each one fires on: the last bar's cross, and how many of each the view holds.
      { id: 'rp:cross', label: 'cross', values: [
        { id: 'last', value: crosses.length ? crosses[crosses.length - 1] ?? 'none' : 'none' },
        { id: 'over', value: crosses.filter(c => c === 'over').length },
        { id: 'under', value: crosses.filter(c => c === 'under').length },
      ] },
      // The volume peaks of the view, and the one on the last bar: what the Pine's peak alert fires on (`KENJI:2455`).
      { id: 'rp:peak', label: 'peak', values: [
        { id: 'last', value: peaks.length ? (peaks[peaks.length - 1] === true ? 'yes' : 'no') : 'off' },
        { id: 'count', value: peaks.filter(Boolean).length },
      ] },
    ];
    return { plots, readout } as StudyOutput;
  },
};
