/**
 * What the address line can say about the material (T-1122): which material and waves to use, and the lens's three numbers, so a person can try
 * a look without waiting for a deploy or fighting the selector. The material and the waves are ordinary settings once applied; the lens
 * numbers are of the session only — they are not saved and never travel in a layout.
 */
import type { Material } from './store.ts';

export interface LensNumbers { readonly radius: number; readonly thickness: number; readonly index: number }
export interface MaterialQuery {
  readonly material?: Material;
  /** Only when the address says it: `?waves=0` or `?waves=1`. */
  readonly waves?: boolean;
  /** The lens's band, displacement and sharpness, when `?lens=r,t,i` is a usable triple. */
  readonly lens?: LensNumbers;
}

const finite = (value: string | null): number | null => {
  if (value === null || value.trim() === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};
const between = (n: number | null, min: number, max: number): number | null => n !== null && n >= min && n <= max ? n : null;

/** Reads the material's commands out of an address's query string. Anything malformed is left out, never guessed half way. */
export function readMaterialQuery(search: string): MaterialQuery {
  const query = new URLSearchParams(search);
  const raw = query.get('material');
  const material: Material | undefined = raw === 'solid' || raw === 'bubble' || raw === 'liquid' ? raw : undefined;
  const rawWaves = query.get('waves');
  const waves = rawWaves === '0' ? false : rawWaves === '1' ? true : undefined;
  const parts = (query.get('lens') ?? '').split(',');
  let lens: LensNumbers | undefined;
  if (parts.length === 3) {
    // The band and the displacement are CSS px (0 to 80 and 0 to 60); the index is how sharply the edge tightens (1 to 6).
    const radius = between(finite(parts[0]!), 0, 80), thickness = between(finite(parts[1]!), 0, 60), index = between(finite(parts[2]!), 1, 6);
    if (radius !== null && thickness !== null && index !== null) lens = { radius, thickness, index };
  }
  return { ...(material ? { material } : {}), ...(waves === undefined ? {} : { waves }), ...(lens ? { lens } : {}) };
}
