/** The reason a dimmed input gives (T-1088): a literal `t()` per declared reason, because the packs check literals, never a variable key. */
function inactiveWords(reason: string | undefined): string {
  switch (reason) {
    case 'Only in the Right style.': return t('Only in the Right style.');
    case 'Needs Orderflow on.': return t('Needs Orderflow on.');
    case 'Only on a forex pair.': return t('Only on a forex pair.');
    // Bookmap's block (T-1190): the range, the bubble's style, the value and the two trigger colours' words.
    case 'Range': return t('Range');
    case 'Bubble style': return t('Bubble style');
    case 'Delta value': return t('Delta value');
    case 'Trigger bullish': return t('Trigger bullish');
    case 'Trigger bearish': return t('Trigger bearish');
    case 'Only with Bubbles.': return t('Only with Bubbles.');
    case 'Bar': return t('Bar');
    case 'HTF': return t('HTF');
    case 'Bubbles': return t('Bubbles');
    case 'Label': return t('Label');
    // Singularity's alert and the trigger's trio (T-1183).
    // Reverse zone's box colours, bell and trigger (T-1184).
    case 'Bullish box': return t('Bullish box');
    case 'Bearish box': return t('Bearish box');
    case 'Alert': return t('Alert');
    case 'Trigger': return t('Trigger');
    case 'Bullish trigger': return t('Bullish trigger');
    case 'Bearish trigger': return t('Bearish trigger');
    case 'Trigger alert': return t('Trigger alert');
    case 'Needs Trigger on.': return t('Needs Trigger on.');
    default: return t('Not in use with the current settings.');
  }
}

/**
 * Which of a piece's inputs count with the values the store holds **now** (T-1176): Pine's `active =` is a condition on those, so it has to be
 * read again after every change instead of once when the panel is built. Pure and exported so the rule can be held without a DOM.
 */
export function activeNow(study: StudyDef, values: InputValues | undefined, market?: string): ReadonlyMap<string, boolean> {
  const now = readInputs(study.inputs, values ?? {});
  return new Map(study.inputs.map(input => [input.id, isInputActive(input, now, market)]));
}

/** The row a declaration asks for; `null` for a kind this build does not know, said in the panel instead of guessing a control. */
export function inputRow(study: StudyDef, input: InputSpec, value: InputValue, set: (value: InputValue) => void): HTMLElement | null {
  // The section's own name is not the row's explanation (T-1325): it is printed once as the header, and a line under the row repeating it said
  // nothing. Only a piece that declares a `hint` — something the name does not say — gets one.
  const name = inputWords(input.name), what = input.hint ? inputWords(input.hint) : '';
  switch (input.kind) {
    case 'bool': return switchRow(name, what, value === true, on => set(on));
    case 'int': return rangeRow(name, what, { min: input.min, max: input.max, step: input.step ?? 1, value: typeof value === 'number' ? value : input.default, format: v => String(Math.round(v)), typed: true }, v => set(Math.round(v)));
    case 'float': return rangeRow(name, what, { min: input.min, max: input.max, step: input.step ?? (input.max - input.min) / 100, value: typeof value === 'number' ? value : input.default, format: v => v.toFixed(input.precision ?? 2), typed: true }, v => set(v));
    case 'string': return input.options?.length
      ? selectRow(name, what, input.options.map(option => [option, optionWords(option)] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v))
      : textRow(name, what, typeof value === 'string' ? value : input.default, v => set(v));
    case 'color': return input.options?.length
      ? selectRow(name, what, input.options.map(option => [option, optionWords(option)] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v))
      : colorRow(name, what, typeof value === 'string' ? value : input.default, v => set(v));
    case 'tf': return selectRow(name, what, Object.keys(TIMEFRAMES).map(tf => [tf, tf] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v));
    case 'source': return selectRow(name, what, input.options.map(option => [option, optionWords(option)] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v));
    default: return null;
  }
}

/** The panel: its switch first (the same as the bar's lamp), then one row an input, in the piece's own order and groups. */
export function buildStudyPanel(store: Store, study: StudyDef, _tools: HTMLElement, body: HTMLElement, rebuild: () => void): void {
  const values = store.state.studyParams[study.id];
  // The window already carries the piece's name in its header, beside the close button (T-1327): printing it again at the top of the body showed
  // "Trend bias" twice, and the same in every panel. The section heads ("Trend continuation") stay: those order the rows.
  // No switch here, for any study, on any pointer (T-1311, T-1313): the deck draws one lamp button per registered study — and Settings → Chart
  // draws it again on a phone, where the deck's row is the one that hides — so a row here would be the same switch a second time. The two pieces
  // the deck skips on purpose are `vwap` (its own panel and button) and `previous-ohlc` (the key levels draw it).
  // A requirement, not a state (T-1304): the piece that needs the minute series under the chart says it in its own words (T-1195), because a
  // chart on one minute has nothing below it for the bookmap to cut its bins with. Whether a load has data is no longer said here: that text
  // appeared and went while the piece loaded, and a panel that grows and shrinks as the data lands moves everything under it.
  const row = studiesStatus().find(item => item.id === study.id);
  if (row?.data?.includes('ltf')) body.append(note(t('This piece needs the one-minute series under the chart, and it is not there: a chart on one minute has nothing below it.')));
  // The opacity slider is gone for every piece (T-1324, the user): it was one row of the same generic control in all of them. The value the
  // painting reads stays in the state, at the default `1`, so nothing that draws depends on a control that no longer exists.
  let group: string | null = null;
  // Pine's `active =` is a condition on the values **at hand** (T-1088), so it is re-read after every change: it used to be evaluated once,
  // before the rows existed, and a switch that only counts under another value stayed disabled until the panel was closed and opened again
  // (T-1176). The rows with a condition are kept and re-judged in place, so a slider is not rebuilt while it is being dragged.
  const conditional: { input: InputSpec; row: HTMLElement; reason: HTMLElement }[] = [];
  const refreshActive = (): void => {
    if (!conditional.length) return;
    // The values as the piece will read them, from the store the last change wrote to, never from the copy this build started with.
    const on = activeNow(study, store.state.studyParams[study.id], store.state.seriesInstrument || store.state.marketId);
    for (const item of conditional) {
      const active = on.get(item.input.id) === true;
      item.row.style.opacity = active ? '' : '0.5';
      for (const control of item.row.querySelectorAll('input, select, button')) (control as HTMLInputElement | HTMLSelectElement | HTMLButtonElement).disabled = !active;
      item.reason.hidden = active;
      item.reason.textContent = active ? '' : inactiveWords(item.input.inactive);
    }
  };
  for (const input of study.inputs) {
    const want = input.group ?? null;
    if (want && want !== group) { body.append(sectionHead(inputWords(want))); group = want; }
    const row = inputRow(study, input, studyInputValue(study, values, input), value => { setStudyParam(store, study.id, input.id, value); refreshActive(); });
    if (!row) { body.append(note(t('{name}: this build has no control for this kind of input.', { name: inputWords(input.name) }))); continue; }
    body.append(row);
    // Only a declared condition gets the reason line; the row itself stays, so the value it holds is never lost.
    if (!input.active) continue;
    const reason = note('');
    body.append(reason);
    conditional.push({ input, row, reason });
  }
  refreshActive();
  if (!study.inputs.length) body.append(note(t('This piece has no inputs of its own.')));
  inspectorRows(body);
}
