import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import { timeframeMs, type Timeframe } from '../engine/time/timeframe.ts';
import type { Bar } from '../engine/series/source.ts';
import { aggregate, autoSecond, autoTimeframe, periodStart } from './htf-candles.ts';
import { biasState } from './trend-bias.ts';

/**
 * `previous-ohlc`: the OEC PREVIOUS OHLC piece — the previous period's open, high, low and close (and the midpoint of its range) for the
 * chart's reference timeframes, which is where the Trade Plan takes its levels from (D-10).
 *
 * The Pine (`OECLiquidityindicators/OddEyeCircle`): `OHLC_DATA_PREV(tf)` (line 99) reads one series per timeframe with `lookahead_on` and
 * takes `[1]` — the previous *completed* period's open/high/low/close plus `(high[1] + low[1]) / 2` as the midpoint; `Previous_OHLC`
 * (2023) draws one line and one label a level, and the calls (2051-2144) do it for 1m, 5m, 15m, 1h, 4h, 1d, 1w and 1M.
 *
 * What the Pine actually draws, and this piece with it: close, high and low of each period (open and the midpoint are commented out in the
 * calls, 2085-2144). They are computed here as values as well and can be switched on (`open`, `mid`), off by default: parity is the three
 * the Pine draws.
 *
 * Two traps from the map (`docs/platform/pieces.md`), both respected: `lookahead_on` means the previous period is the last *completed* one
 * (a forming bar is never used), and the Pine's "1m" series is `Intra_1m_tf = '5'` (line 151) — there is no real 1m series; both P1m and
 * P5m read the 5-minute one.
 *
 * A period whose series the host has not resolved, or whose previous period is not the one right before (a gap), is not drawn: the piece
 * never invents a level. `compute` is pure and imports no hub, store or fetch; the engine's painter draws the plots.
 */
interface Period { readonly id: string; readonly code: string; readonly label: string; readonly series: Timeframe; readonly color: string }

/** The Pine's calls in their order; 1m and 5m share the 5-minute series (`Intra_1m_tf`, 151). */
const PERIODS: readonly Period[] = [
  { id: 'p1m', code: 'P1m', label: 'Prev. 1m (5m series)', series: '5', color: '#11ff40' },
  { id: 'p5m', code: 'P5m', label: 'Prev. 5m', series: '5', color: '#11ff40' },
  { id: 'p15m', code: 'P15m', label: 'Prev. 15m', series: '15', color: '#11ff40' },
  { id: 'p1h', code: 'P1H', label: 'Prev. 1H', series: '60', color: '#11ff40' },
  { id: 'p4h', code: 'P4H', label: 'Prev. 4H', series: '240', color: '#ff9800' },
  { id: 'pd', code: 'PD', label: 'Prev. Day', series: 'D', color: '#08bcd4' },
  { id: 'pw', code: 'PW', label: 'Prev. Week', series: 'W', color: '#fffcbc' },
  { id: 'pm', code: 'PM', label: 'Prev. Month', series: 'M', color: '#08d48c' },
];

const SERIES: readonly Timeframe[] = ['5', '15', '60', '240', 'D', 'W', 'M'];

/** The bar size of each series, in ms. */
const SERIES_MS: Readonly<Record<string, number>> = {
  '5': 5 * 60_000, '15': 15 * 60_000, '60': 3_600_000, '240': 14_400_000, D: 86_400_000, W: 604_800_000, M: 2_592_000_000,
};

/**
 * The Pine's own gate, copied as it is (`GlobalFunctions library:192-197`). A chart belongs to one **family** and only that family's
 * previous periods are drawn: `show_W()` is a 1m, 15m or 4H intraday chart or a weekly one; `show_M()` is a seconds chart, a 5m or 1H
 * intraday one, a daily or a monthly one. The monthly level is the exception: its call asks `show_below_equal_M()` (`:235`), true on
 * everything but a seconds chart. A 30-minute chart belongs to neither family and draws only the monthly level, as the Pine does.
 * A chart with no bars yet (`chartMs` 0) filters nothing.
 */
export function showsPeriod(chartMs: number, period: string): boolean {
  if (!(chartMs > 0)) return true;
  const minutes = chartMs / 60_000;
  const seconds = chartMs < 60_000;
  const daily = chartMs >= 86_400_000 && chartMs < 604_800_000;
  const weekly = chartMs >= 604_800_000 && chartMs < 2_592_000_000;
  const monthly = chartMs >= 2_592_000_000;
  const intraday = !seconds && !daily && !weekly && !monthly;
  const showW = (intraday && (minutes === 1 || minutes === 15 || minutes === 240)) || weekly;
  const showM = seconds || (intraday && (minutes === 5 || minutes === 60)) || daily || monthly;
  const belowEqualM = !seconds;
  switch (period) {
    case 'p1m': case 'p15m': case 'p4h': case 'pw': return showW;
    case 'p5m': case 'p1h': case 'pd': return showM;
    case 'pm': return belowEqualM;
    default: return true;
  }
}

/** The chart's own bar size: the piece is told bars, not the chart's timeframe name. */
function chartBarMs(bars: readonly Bar[]): number {
  for (let index = 1; index < bars.length; index += 1) {
    const step = bars[index]![0] - bars[index - 1]![0];
    if (step > 0) return step;
  }
  return 0;
}

/** The inputs that change the result: each period and level on/off with its colour, plus the three the Pine keeps commented out. */
const INPUTS: readonly InputSpec[] = [
  ...PERIODS.flatMap((period): InputSpec[] => [
    { id: `${period.id}.on`, kind: 'bool', name: period.label, default: true, group: 'Periods' },
    { id: `${period.id}.high`, kind: 'bool', name: `${period.code} high`, default: true, group: 'Levels' },
    { id: `${period.id}.low`, kind: 'bool', name: `${period.code} low`, default: true, group: 'Levels' },
    { id: `${period.id}.close`, kind: 'bool', name: `${period.code} close`, default: true, group: 'Levels' },
    { id: `${period.id}.color`, kind: 'color', name: `${period.code} colour`, default: period.color, group: 'Style' },
  ]),
  { id: 'open', kind: 'bool', name: 'Open (not drawn by the Pine)', default: false, group: 'Levels' },
  { id: 'mid', kind: 'bool', name: '50% (not drawn by the Pine)', default: false, group: 'Levels' },
  { id: 'width', kind: 'int', name: 'Width', default: 1, min: 1, max: 5, group: 'Style' },
  { id: 'style', kind: 'string', name: 'Style', default: 'dotted', options: ['solid', 'dashed', 'dotted'], group: 'Style' },
  { id: 'hierarchy', kind: 'bool', name: 'Follow the chart timeframe', default: true, group: 'Periods' },
  { id: 'labels', kind: 'bool', name: 'Labels', default: true, group: 'Style' },
  { id: 'prices', kind: 'bool', name: 'Price in the label', default: true, group: 'Style' },
  // `group_PREVIOUSOHLC` (`OEC:129-141`), the ten the port lacked (T-1186). `show_previousOHLC` is the piece's lamp; `show_tf_orderflow` is the
  // HTF orderflow block's switch, which the product turns on per piece, so those four say what they need in their own words.
  { id: 'displaystyle', kind: 'string', name: 'Display', default: 'Future', options: ['Future', 'Right'], group: 'Display' },
  { id: 'anchor', kind: 'int', name: 'Anchor', default: 40, min: 0, max: 500, group: 'Display', active: v => v['displaystyle'] === 'Right', inactive: 'Only in the Right style.' },
  { id: 'extend', kind: 'int', name: 'Extend', default: 250, min: 5, max: 500, group: 'Display', active: v => v['displaystyle'] === 'Right', inactive: 'Only in the Right style.' },
  { id: 'text', kind: 'string', name: 'Text', default: 'Small', options: ['Tiny', 'Small', 'Normal'], group: 'Display' },
  { id: 'short', kind: 'bool', name: 'Short', default: true, group: 'Display' },
  { id: 'compact', kind: 'bool', name: 'Compact', default: true, group: 'Display' },
  { id: 'compactOrderflow', kind: 'bool', name: 'Orderflow (compact)', default: true, group: 'Display', active: v => v['compact'] === true, inactive: 'Only with Compact on.' },
  { id: 'fillOrderflow', kind: 'bool', name: 'Fill', default: true, group: 'Display', active: v => v['compact'] === true, inactive: 'Only with Compact on.' },
  { id: 'bullColor', kind: 'color', name: 'Bullish', default: '#73c3e1', group: 'Display', active: v => v['compact'] === true, inactive: 'Only with Compact on.' },
  { id: 'bearColor', kind: 'color', name: 'Bearish', default: '#ffc0b2', group: 'Display', active: v => v['compact'] === true, inactive: 'Only with Compact on.' },
];

/**
 * The start of the period right before the one `start` begins: the previous day, week (`start - 7 days`, Monday to Monday) or month, or
 * the previous bar for the fixed sizes. Used to refuse a series whose gap leaves an older period as "the previous one".
 */
export function previousStart(start: number, tf: Timeframe): number {
  if (tf === 'D') return start - timeframeMs('D');
  if (tf === 'W') return start - timeframeMs('W');
  if (tf === 'M') { const date = new Date(start); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() - 1, 1); }
  return start - timeframeMs(tf);
}

/** The previous completed bar of `tf` at `now`, or null when the series does not hold the period right before the current one. */
export function previousBar(bars: readonly Bar[], now: number, tf: Timeframe): Bar | null {
  const start = periodStart(now, tf), wanted = previousStart(start, tf);
  for (const bar of bars) if (bar[0] === wanted) return bar;
  return null;
}

const dashOf = (style: string): readonly number[] => style === 'solid' ? [] : style === 'dashed' ? [6, 4] : [2, 3];
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] : fallback;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const priceText = (value: number): string => Number(value.toFixed(2)).toString();

/**
 * One level of one frame, as numbers and words rather than as a drawing: the frame's code (`P4H-H`), its colour and the stretch it runs
 * across (the previous period, from its start to the current one's). This is what T-1068 needs to draw the levels with the key levels'
 * own line and label instead of this piece's plots: the numbers stay here, the drawing moves.
 */
export interface PreviousLevel {
  readonly frame: string;
  readonly code: string;
  readonly price: number;
  readonly color: string;
  readonly from: number;
  readonly to: number;
  /** The period's orderflow side (`biasState`): what the block's `Orderflow` colours the line and its label with (`OEC:138-141`). */
  readonly bias?: 'bull' | 'bear' | 'neutral';
  /** Which of the period's three levels it is: the close runs on, the high and the low stop where price reaches them (T-1222). */
  readonly what?: 'high' | 'low' | 'close';
  /**
   * The first bar that traded through the level, or null while price has not reached it. The Pine checks the touch on every bar even when the line
   * is not being painted that bar (`OEC:1377-1390`): checked only at paint time, the touches in between were lost.
   */
  readonly touched?: number | null;
  /** Whether it is the newest completed period's level: that is the one never dimmed (`OEC:1433-1435`). */
  readonly newest?: boolean;
}

/**
 * The frames the HTF candles and trend-bias draw on this chart (`auto_htfPDA` and `auto_htfPDA_candle_2`, `GlobalFunctions:304-345`): the
 * key levels' hierarchy keeps the levels of these timeframes and no other (T-1198), so the levels and the candles agree about the family.
 */
export function familyFrames(chartMs: number): readonly Timeframe[] {
  if (!(chartMs > 0)) return [];
  const first = autoTimeframe(chartMs, 'htf-pda'), second = autoSecond(chartMs);
  return first === second ? [first] : [first, second];
}

/**
 * The levels the piece publishes, without drawing them. `barsOf` answers the candles of a series, or null when the host could not resolve
 * it: a period whose series is missing, or whose previous period is not the one right before it, contributes nothing (never a level from
 * another period). The hierarchy filter is the Pine's own (`showsPeriod`), applied only when the input is on.
 *
 * The candle of each period is **folded here** with the same `periodStart`/`aggregate` that `htf-candles` draws with (D-34): the host may
 * hand bars stamped at the exchange's own day, and folding them makes `PDC`/`PWH`/`PMC` the close of the very candle the chart draws.
 * A period the series does not hold from its own start is not drawn — half a day is not a day.
 */
export function previousLevels(now: number, barsOf: (tf: Timeframe) => readonly Bar[] | null, params: InputValues, chartMs: number): PreviousLevel[] {
  const open = flag(params, 'open'), mid = flag(params, 'mid'), hierarchy = flag(params, 'hierarchy');
  const levels: PreviousLevel[] = [];
  for (const period of PERIODS) {
    if (!flag(params, `${period.id}.on`)) continue;
    // The hierarchy is the Pine's own gate for **all eight** frames (T-1221): `showsPeriod` (`GlobalFunctions:192-197`), the same rule the
    // piece was written with. A chart belongs to one family (W: 1m, 15m, 4H, week; M: 5m, 1H, day), and the month is `belowEqualM`, true on
    // everything but a seconds chart — which is why the month is the one level that appears in both families.
    if (hierarchy && chartMs > 0 && !showsPeriod(chartMs, period.id)) continue;
    const bars = barsOf(period.series);
    if (!bars) continue;
    const start = periodStart(now, period.series), from = previousStart(start, period.series), color = text(params, `${period.id}.color`, period.color);
    // The history must reach back before the period began: a series that starts inside it would hand half a candle back as if it were whole.
    if (bars[0]![0] > from) continue;
    const groups = aggregate(bars, period.series);
    const index = groups.findIndex(group => group.start === from);
    if (index < 0) continue;
    const bar = groups[index]!;
    // The frame's state with the rule the table and the HTF candles already read (`biasState`): a bullish close marks the high, a bearish
    // one the low, and a **neutral** close marks both — what the person asked on 2026-11-02 for daily, weekly and monthly alike. With no
    // earlier period to compare against (the series begins at this one) both are published, never one chosen by a guess.
    const before = index > 0 ? groups[index - 1]! : null;
    const bias = before ? biasState([asBar(before, 0), asBar(bar, 1), asBar(bar, 2)]) : null;
    const both = bias === null || bias === 'neutral';
    // A box that is on is drawn (T-1209): the period's side says its **colour**, never whether it exists. A **neutral** close draws its high and
    // its low whether or not those boxes are on (T-1222), which is the Pine's own gate: each call passes `(the box) or (keylevels_compact_orderflow
    // and the period's colour is the neutral one)` — `OEC:1532` for 4H, `:1539` day, `:1545` week, `:1554` month.
    const neutralHL = flag(params, 'compactOrderflow') && both;
    const wanted: { suffix: string; value: number; on: boolean; what: 'high' | 'low' | 'close' }[] = [
      { suffix: 'C', value: bar.close, on: flag(params, `${period.id}.close`), what: 'close' },
      { suffix: 'H', value: bar.high, on: flag(params, `${period.id}.high`) || neutralHL, what: 'high' },
      { suffix: 'L', value: bar.low, on: flag(params, `${period.id}.low`) || neutralHL, what: 'low' },
    ];
    if (open) wanted.push({ suffix: 'O', value: bar.open, on: true, what: 'close' });
    if (mid) wanted.push({ suffix: '50%', value: (bar.high + bar.low) / 2, on: true, what: 'close' });
    const side: 'bull' | 'bear' | 'neutral' = bias === null ? 'neutral' : bias === 'bullish' || bias === 'pre-bullish' ? 'bull' : bias === 'bearish' || bias === 'pre-bearish' ? 'bear' : 'neutral';
    // The touch is looked for from the bar the level was born in, and on every bar, drawn or not (T-1222): the Pine does the same
    // (`OEC:1377-1390`) — checked only while painting, the touches of the bars in between were lost.
    const touchedAt = (price: number): number | null => {
      for (const row of bars) {
        if (row[0]! < from) continue;
        if (row[3]! <= price && price <= row[2]!) return row[0]!;
      }
      return null;
    };
    for (const level of wanted) {
      if (!level.on) continue;
      levels.push({
        frame: period.id, code: `${period.code}-${level.suffix}`, price: level.value, color,
        // The Pine starts a high or a low at the **previous** period's start (`daily_time_prev`, `OEC:1539`) and a close at the current one
        // (`daily_time`, `:1538`); `_xt` is that time (`:1420`). A touched low that began at the current period would be a bar long (T-1224).
        from: level.what === 'close' ? start : from, to: start, bias: side,
        what: level.what, touched: touchedAt(level.value), newest: true,
      });
    }
  }
  return levels;
}

/** A folded candle as the `Bar` shape `biasState` reads: it judges the close against the high and the low of the one before. */
const asBar = (group: { open: number; high: number; low: number; close: number }, start: number): Bar => [start, group.open, group.high, group.low, group.close, 0];

export const PREVIOUS_OHLC: StudyDef = {
  api: STUDY_API,
  id: 'previous-ohlc',
  name: 'Previous OHLC',
  inputs: INPUTS,
  data: [
    // The chart's own candles, for the hierarchy rule only: nothing of them is drawn.
    { key: 'chart', kind: 'candles' as const, label: 'Chart candles' },
    ...SERIES.map(tf => ({ key: `series:${tf}`, kind: 'candles' as const, label: `${tf} candles` })),
  ],
  compute(ctx): StudyOutput | null {
    const params = readInputs(INPUTS, ctx.params);
    const chart = ctx.data.candles('chart');
    const chartMs = chart ? chartBarMs(chart.bars) : 0;
    const levels = previousLevels(ctx.now, tf => ctx.data.candles(`series:${tf}`)?.bars ?? null, params, chartMs);
    if (!levels.length) return null;
    const labels = flag(params, 'labels'), prices = flag(params, 'prices');
    const width = Math.max(1, Math.min(5, Math.round(number(params, 'width', 1)))), dash = dashOf(text(params, 'style', 'dotted'));
    // `keylevels_text` (`:134`) is the label's size; the painter draws it with the piece's own (`tiny` / `small` / `normal`).
    const sizeName = text(params, 'text', 'Small').toLowerCase();
    const size: 'tiny' | 'small' | 'normal' = sizeName === 'tiny' ? 'tiny' : sizeName === 'normal' ? 'normal' : 'small';
    // `Right` (`:129-131`) runs every level from `timenow + anchor` to `timenow + extend`, the same `limit_right` the zones use (`GF:281-282`).
    const barMs = chart && chart.bars.length > 1 ? chart.bars[1]![0] - chart.bars[0]![0] : 0;
    const right = text(params, 'displaystyle', 'Future') === 'Right' && barMs > 0;
    const rightFrom = ctx.now + Math.max(0, Math.round(number(params, 'anchor', 40))) * barMs;
    const rightTo = ctx.now + Math.max(5, Math.round(number(params, 'extend', 250))) * barMs;
    // `keylevels_compact` (`:137`): two levels at the very same price are one line with both codes, as the Pine's `f_LevelMerge` draws them.
    const compact = flag(params, 'compact');
    const drawn = compact
      ? [...new Map(levels.map(level => [`${level.price}`, level])).keys()].map(key => {
        const group = levels.filter(level => `${level.price}` === key);
        const first = group[0]!;
        return { ...first, code: group.map(level => level.code).join(' · ') };
      })
      : levels;
    const plots: Plot[] = [];
    for (const level of drawn) {
      const t0 = right ? rightFrom : level.from, t1 = right ? rightTo : level.to;
      plots.push({ kind: 'line', points: [{ t: t0, p: level.price }, { t: t1, p: level.price }], style: { width, color: level.color, dash } });
      // `keylevels_globalshort` (`:135`): the short word is the code alone, the long one names the period before it.
      const name = flag(params, 'short') ? level.code : `Previous ${level.code}`;
      if (labels) plots.push({ kind: 'label', t: t1, p: level.price, text: prices ? `${name} ${priceText(level.price)}` : name, color: level.color, size });
    }
    // The same numbers, as named values (D-31): the app's key-level painter reads them from here, so the frames are drawn once.
    // The numbers the app's key-level painter draws from (`T-1068`): `Right` moves them too, so the drawn line and the published one agree.
    const readout = levels.map(level => ({
      id: `frame:${level.frame}:${level.code}`,
      label: level.code,
      values: [
        { id: 'price', value: level.price }, { id: 'from', value: right ? rightFrom : level.from }, { id: 'to', value: right ? rightTo : level.to },
        { id: 'color', value: level.color },
      ],
    }));
    return { plots, readout };
  },
};
