import { CANDLE_VENUES, CANDLE_VENUE_KIND } from '../../shared/history.ts';
import { instrumentIdFor, type Coin, type CoinVenue } from '../../shared/coins.ts';
import { historyTarget, type HistoryTarget } from '../keylevels/history.ts';
import { parsePick, readPicks } from '../market-choice.ts';

/**
 * Whose candles a line is worked out from (T-1321, for the TPO; the Volume profile and the VWAP ask the same question): the chart's market
 * — or the one that stands in for it where its history cannot be read (`historyTarget`) —, or markets a person picks, added up bar by bar.
 *
 * This is the **re-made** module, not a copy of the original's: the pick and its form (`binance/perp`, `bybit/spot`) already exist in
 * `market-choice.ts` (`parsePick`, `readPicks`, `MAX_PICKS`), so nothing of that is written a second time here, and the candle venue a pick
 * stands for is **derived from what the page already reads** (`CANDLE_VENUES` and `CANDLE_VENUE_KIND`, `shared/history.ts:200`) instead of a second literal table of
 * eleven pairs. The original's `VENUE_OF` and `isVwapPick` are therefore not duplicated: their job is done by the two rules below.
 */
export type VwapSource = 'chart' | 'chosen';

/** The most markets one set of lines adds up (the original's limit; the pick list's own cap is wider, `MAX_PICKS`). */
export const MAX_VWAP_MARKETS = 6;

/**
 * Saved picks, checked: the form the footprint uses (`readPicks`), each once, at most `MAX_VWAP_MARKETS`, and only the ones this page can
 * actually read candles for (`pickVenue`). That last filter is the original's `isVwapPick`: it had a literal list of eleven pairs, and here
 * the list *is* what `CANDLE_VENUES` answers, so an exchange the page cannot read is never offered nor kept from a file.
 */
export function readVwapPicks(value: unknown): string[] {
  return readPicks(value, false).filter(pick => pickVenue(pick) !== null).slice(0, MAX_VWAP_MARKETS);
}

/**
 * The candle venue a pick stands for on this page: `binance/spot` is `binancespot` and `binance/perp` is `binance`; a market whose id has no
 * kind suffix is its exchange's own (`coinbase`), and the kind it is comes **from the venue list itself** (`CANDLE_VENUE_KIND`,
 * `shared/history.ts`): `coinbase` is spot and `hyperliquid` perpetual, which a name cannot say. `null` when the page cannot read that
 * market's candles at all — including a kind the exchange does not have (`hyperliquid/spot`, `coinbase/perp`).
 */
export function pickVenue(pick: string): string | null {
  const parsed = parsePick(pick);
  if (!parsed) return null;
  const { family, kind } = parsed;
  return CANDLE_VENUES.find(venue => candleFamily(venue) === family && CANDLE_VENUE_KIND[venue] === kind) ?? null;
}

/** The exchange a candle venue belongs to: `binancespot` is Binance's spot market and `binance` its perpetual, so both are `binance`. */
const candleFamily = (venue: string): string => (venue.endsWith('spot') ? venue.slice(0, -'spot'.length) : venue);

/** The chart's market as the page names it for its candles (a server names Binance spot `binance:BTCUSDT:spot`, the history `binancespot:BTCUSDT`). */
const chartCandleId = (chartId: string): string => { const spot = /^([^:]+):(.+):spot$/.exec(chartId); return spot ? `${spot[1]}spot:${spot[2]}` : chartId; };

/** The market a pick stands for on `coin`, or null where the coin is not listed there or its candles cannot be read. */
export function pickTarget(pick: string, coin: Coin, chartId: string): HistoryTarget | null {
  const venue = pickVenue(pick);
  if (!venue) return null;
  const listing = coin.markets[venue as CoinVenue], id = instrumentIdFor(venue, coin);
  if (!listing || !id) return null;
  const own = id === chartCandleId(chartId), target = historyTarget(id, coin);
  return target ?? { id, listing, own };
}

/**
 * The picks the page offers, in the candle list's order (perpetual before spot on an exchange that has both): each is an exchange and a
 * kind, `pickOf(family, kind)`, the form `market-choice.ts` saves.
 */
export const VWAP_PICKS: readonly string[] = CANDLE_VENUES.flatMap(venue => {
  const kind = CANDLE_VENUE_KIND[venue]!;
  return [`${candleFamily(venue)}/${kind}`];
});

/** The market a saved pick names on `coin`, or none where its candles cannot be read (the chart market's own included, as the original's). */
export function vwapTargets(source: VwapSource, picks: readonly string[], chartId: string, coin: Coin): HistoryTarget[] {
  if (source === 'chart') { const one = historyTarget(chartId, coin); return one ? [one] : []; }
  const out: HistoryTarget[] = [];
  for (const pick of picks) {
    const target = pickTarget(pick, coin, chartId);
    if (target && !out.some(t => t.id === target.id)) out.push(target);
    if (out.length >= MAX_VWAP_MARKETS) break;
  }
  return out;
}

/** The pick that stands for a market (`binancespot:BTCUSDT` is `binance/spot`), or null for one the page does not read candles for. */
export function pickOfMarket(id: string): string | null {
  const venue = id.split(':')[0]!, pick = VWAP_PICKS.find(p => pickVenue(p) === venue);
  return pick ?? null;
}

/**
 * The picks a person starts from when switching to chosen markets: the market the blocks read now (the chart's, or the one standing in for
 * it), so nothing changes until a box is ticked.
 */
export function seedPicks(chartId: string, coin: Coin): string[] {
  const target = historyTarget(chartId, coin), pick = target ? pickOfMarket(target.id) : null;
  return pick ? [pick] : [];
}
