import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec } from '../engine/inputs/schema.ts';
import { isTimeframe, timeframeMs, type Timeframe } from '../engine/time/timeframe.ts';
import type { Bar } from '../engine/series/source.ts';
import { biasState, type BiasState } from './trend-bias.ts';

/**
 * `htf-candles`: the OEC TIMEFRAME CANDLES ported to the study contract — candles of a higher timeframe drawn to the right of the chart.
 *
 * The Pine it comes from (`OECLiquidityindicators/OddEyeCircle`): a new HTF candle starts when the HTF period's start time changes
 * (`newDay_tf_1`, lines 1936-1956), the candle is given the bar's open/high/low/close (`newDC_tf_1`, 1212-1235) and every bar updates its
 * high, low and close (`updateDC_tf_1`, 1240-1265); the drawing places them right of the last bar (`drawDC_tf_1`, 1284-1335:
 * `position = bar_index + offset + (count - i) * 3`, the body two bars wide, the wick in the middle).
 *
 * One computation, two styles: `candle` draws the body and the wick, `ohlc` the high-low bar with its open and close ticks. The style is an
 * input, never a second path through the aggregation.
 *
 * The card's other half (KENJI FORCE/TREND) is not a candle style in its Pine: it is a macro bias table (VIX, DXY, PCCE, USDT.D with
 * percent thresholds, `KENJI` lines 352-370 and 660-720). See the card's Notas: it needs the user's correction before it is a piece.
 *
 * `compute` is pure (same input, same output), imports no hub, store or fetch, and returns plots; the engine's painter
 * (`engine/draw/painter.ts`) is the `render(Scope)` that draws them, so this file never touches a canvas.
 */
const MINUTE = 60_000, DAY = 86_400_000, WEEK = 604_800_000;

const INPUTS: readonly InputSpec[] = [
  { id: 'type', kind: 'string', name: 'Type', default: 'htf-pda', options: ['custom', 'htf-pda', 'htf-pda-w', 'htf-pda-m'], group: 'Timeframe candles' },
  // Pine's `tf_candles_tf_1` (`:114`, read at `:368`): empty is auto (`auto_htfPDA`), never a fixed `60` (T-1170).
  { id: 'timeframe', kind: 'string', name: 'Timeframe', default: 'auto', options: ['auto', '5', '15', '60', '240', 'D', 'W', 'M'], group: 'Timeframe candles' },
  { id: 'style', kind: 'string', name: 'Style', default: 'candle', options: ['candle', 'ohlc'], group: 'Timeframe candles' },
  { id: 'count', kind: 'int', name: 'Candles', default: 6, min: 4, max: 10, group: 'Timeframe candles' },
  // Not a Pine input (its second call reuses the first's count): the second frame gets its own number (T-1086, D-36).
  // Pine's `tf_candles_number_bars_tf_2` (`:117`) allows three, one under the first call's floor (T-1170).
  { id: 'count2', kind: 'int', name: 'Candles (second frame)', default: 6, min: 3, max: 10, group: 'Timeframe candles' },
  { id: 'offset', kind: 'int', name: 'Offset', default: 80, min: 5, max: 100, group: 'Timeframe candles' },
  // Pine's `tf_candles_dual_mode` (`:111`) ships on: two frames are the default drawing, not the option (T-1170).
  { id: 'dual', kind: 'bool', name: 'Two frames', default: true, group: 'Timeframe candles' },
  // Pine's `tf_candles_tf_2` (`:164`) is empty for auto, and its empty value is `auto_htfPDA_candle_2()` (`GlobalFunctions:340`), never `D`:
  // with `D` a 1h chart's second frame named the same frame as the first and `framePlan` dropped it — no second frame, ever (T-1145).
  { id: 'second', kind: 'string', name: 'Second timeframe', default: 'auto', options: ['auto', '5', '15', '60', '240', 'D', 'W', 'M'], group: 'Timeframe candles' },
  { id: 'label', kind: 'bool', name: 'Timeframe label', default: true, group: 'Style' },
  // Pine's `tf_ohlc_label` (`:119`): the `A`/`D`/`M` letters of the OHLC style, apart from the timeframe box (`:118`), and off the panel's
  // reach unless that style is the one drawn — `active = show_tf_candles and tf_candles_style == 'OHLC'` (T-1175).
  { id: 'ohlcLabel', kind: 'bool', name: 'OHLC labels', default: true, group: 'Style', active: values => values['style'] === 'ohlc' },
  // `trend_orderflow` (`OEC:2199`): on, the candle takes the frame's bias (`biasTextColor_X`); off, `close > open` (`c_tf_orderflow_up/dn`).
  { id: 'orderflow', kind: 'bool', name: 'Colour by bias', default: true, group: 'Style' },
  // Pine's neutral bias colour (`trend_biasneutral_close_css`, `OEC:117`), the one its candles take inside the previous range.
  { id: 'neutral', kind: 'color', name: 'Neutral', default: '#5d606b', group: 'Style' },
  { id: 'bull', kind: 'color', name: 'Bullish', default: '#73c3e1', group: 'Style' },
  { id: 'bear', kind: 'color', name: 'Bearish', default: '#ffc0b2', group: 'Style' },
  { id: 'wick', kind: 'color', name: 'Wick', default: '#ffffff', group: 'Style' },
  // Pine's `tf_label_css` (`:124`): the colour of the O/C, the H/L and the timeframe box, its own input apart from the wick. The Pine
  // uses it only when the theme is `Custom` and the chart foreground otherwise; the product has one palette, so it is the value drawn.
  { id: 'labelColor', kind: 'color', name: 'Label colour', default: '#ffffff', group: 'Style' },
];

type HtfType = 'custom' | 'htf-pda' | 'htf-pda-w' | 'htf-pda-m';
type Style = 'candle' | 'ohlc';

interface HtfBar { start: number; open: number; high: number; low: number; close: number }

/** The bar size the chart's candles are on, from their own starts (a study is told the bars, not the page's timeframe name). */
function barSize(bars: readonly Bar[]): number {
  for (let index = 1; index < bars.length; index += 1) {
    const step = bars[index]![0] - bars[index - 1]![0];
    if (step > 0) return step;
  }
  return MINUTE;
}

/**
 * Pine's `auto_htfPDA`, `_W` and `_M` (`GlobalFunctions library` 304-345), on the bar size instead of the page's timeframe id. Pine answers
 * `12M` above a week and the engine has no 12-month timeframe: a month is the highest it holds, and the piece says so in its own options.
 */
export function autoTimeframe(chartMs: number, type: Exclude<HtfType, 'custom'>): Timeframe {
  const minutes = chartMs / MINUTE, intraday = chartMs < DAY;
  if (type === 'htf-pda-w') {
    if (intraday) return minutes < 15 ? '15' : minutes < 240 ? '240' : 'W';
    return chartMs === DAY ? 'W' : 'M';
  }
  if (type === 'htf-pda-m') {
    if (intraday) return minutes < 5 ? '5' : minutes < 60 ? '60' : 'D';
    return 'M';
  }
  if (intraday) return minutes < 5 ? '15' : minutes < 15 ? '60' : minutes < 60 ? '240' : minutes < 240 ? 'D' : 'W';
  return 'M';
}

/**
 * The bias of the frame's candle at `index`, with the rule `trend-bias` already ports (`biasState`, `OEC:834-900`): it reads the candle
 * against the one before it, so the list is built with the candle in the middle (that function treats its last element as the forming one).
 */
function biasOfFrame(groups: readonly { open: number; high: number; low: number; close: number }[], index: number): BiasState | null {
  if (index < 1) return null;
  const target = groups[index]!, before = groups[index - 1]!;
  const asBar = (group: typeof target, start: number): Bar => [start, group.open, group.high, group.low, group.close, 0];
  return biasState([asBar(before, 0), asBar(target, 1), asBar(target, 2)]);
}

/** The start of the period `t` falls in: Pine's `timeframe.change` boundaries, in UTC (the page's candles are exchange-stamped and its days, weeks and months start at 00:00, Monday and the 1st, UTC). */
export function periodStart(t: number, tf: Timeframe): number {
  if (tf === 'D') return Math.floor(t / DAY) * DAY;
  if (tf === 'W') {
    const day = Math.floor(t / DAY) * DAY, weekday = new Date(day).getUTCDay();
    return day - ((weekday + 6) % 7) * DAY; // Monday
  }
  if (tf === 'M') { const date = new Date(t); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1); }
  return Math.floor(t / timeframeMs(tf)) * timeframeMs(tf);
}

/**
 * How far the second frame starts after the first, in chart bars: the Pine's `+ 40` (`OddEyeCircle:1669`), fixed and not a gap worked out
 * from the candle count. With `count = 6` the first frame ends 18 bars out and the second begins 43, so 25 bars of air between them — the
 * room its own timeframe box (`'TF\n'` at `position + 20`, `:1497`) is drawn in.
 */
export const DUAL_GAP = 40;

/**
 * The frames to draw and where each starts, in chart bars after the last one (T-0044): one, or with the dual mode on two — the automatic
 * one (or the fixed one) and the second the person chose, as the Pine's `tf_candles_tf_2`. Both frames place their candles the same way
 * (`(count - i) * 3`, `:1301` and `:1669`); the second starts `DUAL_GAP` bars further out, exactly as the Pine does. A second frame equal to
 * the first adds nothing.
 */
/**
 * The second frame the Pine draws when nobody names one: `auto_htfPDA_candle_2` (`GlobalFunctions library:340`), the frame one step coarser than
 * `auto_htfPDA`. Intraday it goes 1m→4H, 5m→W, 15m→W, 1h→M, 4h→M; daily and coarser it is `12M`, which this page reads as `M` (declared).
 */
export function autoSecond(chartMs: number): Timeframe {
  const minutes = Math.round(chartMs / MINUTE);
  if (chartMs < DAY) {
    if (minutes < 5) return '240';
    if (minutes < 15) return 'D';
    if (minutes < 60) return 'W';
    return 'M';
  }
  return 'M';
}

/**
 * Moves the whole table left until its newest candle is inside the view (T-1149). The Pine places the frames `offset` bars past the last bar on a
 * chart that keeps room to its right; a page whose view ends at the live edge has none, so with the second frame's count at ten most of its candles
 * were drawn past the right edge and the person saw two. One shift for every frame: their distance is what the Pine draws, not something to fix.
 */
export function withinView(plots: readonly Plot[], t1: number, chartMs: number): Plot[] {
  const limit = t1 - chartMs;
  let right = -Infinity, left = Infinity;
  for (const plot of plots) {
    if (plot.kind === 'box') { right = Math.max(right, plot.t1); left = Math.min(left, plot.t0); }
    else if (plot.kind === 'line') for (const point of plot.points) { right = Math.max(right, point.t); left = Math.min(left, point.t); }
    else if (plot.kind === 'label') { right = Math.max(right, plot.t); left = Math.min(left, plot.t); }
  }
  if (!Number.isFinite(right) || right <= limit) return [...plots];
  // The table is pulled in only when **nothing** of it would be seen — its left edge is already past the view's right one. Moving it
  // whenever its right edge passed also pinned it to the edge and left the offset slider with nothing to move (T-1176, measured: offsets
  // 5/40/80 all landed at the edge). A table that is partly out is drawn where the Pine puts it, and scrolling shows the rest.
  if (!Number.isFinite(left) || left <= limit) return [...plots];
  const shift = right - limit;
  return plots.map((plot): Plot => {
    if (plot.kind === 'box') return { ...plot, t0: plot.t0 - shift, t1: plot.t1 - shift };
    if (plot.kind === 'line') return { ...plot, points: plot.points.map(point => ({ ...point, t: point.t - shift })) };
    if (plot.kind === 'label') return { ...plot, t: plot.t - shift };
    return plot;
  });
}

export function framePlan(tf: Timeframe, dual: boolean, offset: number, second: Timeframe = 'D', count = 6, count2 = count): { tf: Timeframe; offset: number; count: number }[] {
  const frames = [{ tf, offset, count }];
  if (dual && second !== tf) frames.push({ tf: second, offset: offset + DUAL_GAP, count: count2 });
  return frames;
}

/** The chart's bars folded into the higher timeframe: a new candle when the period's start changes, then high, low and close follow (`newDC_tf_1` / `updateDC_tf_1`). */
export function aggregate(bars: readonly Bar[], tf: Timeframe): HtfBar[] {
  const out: HtfBar[] = [];
  for (const bar of bars) {
    const start = periodStart(bar[0], tf), last = out[out.length - 1];
    if (!last || last.start !== start) {
      out.push({ start, open: bar[1], high: bar[2], low: bar[3], close: bar[4] });
      continue;
    }
    last.high = Math.max(last.high, bar[2]);
    last.low = Math.min(last.low, bar[3]);
    last.close = bar[4];
  }
  return out;
}

/** The exchange's own bars of a frame, as the candles drawn: its `start` is the period's, so no folding is needed (T-1173). Only those up to the chart's last bar, so both frames end at the same place. */
function framesOf(bars: readonly Bar[], upTo: number): HtfBar[] {
  const out: HtfBar[] = [];
  for (const bar of bars) {
    if (bar[0] > upTo) break;
    out.push({ start: bar[0], open: bar[1], high: bar[2], low: bar[3], close: bar[4] });
  }
  return out;
}

const TIMEFRAME_NAMES: Readonly<Record<Timeframe, string>> = { '1': '1m', '5': '5m', '15': '15m', '30': '30m', '60': '1H', '240': '4H', D: 'D', W: 'W', M: 'M' };

export const HTF_CANDLES: StudyDef = {
  api: STUDY_API,
  id: 'htf-candles',
  name: 'Higher-timeframe candles',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 2) return null;
    const params = readInputs(INPUTS, ctx.params);
    const type: HtfType = params['type'] === 'custom' || params['type'] === 'htf-pda' || params['type'] === 'htf-pda-w' || params['type'] === 'htf-pda-m' ? params['type'] : 'htf-pda';
    const style: Style = params['style'] === 'ohlc' ? 'ohlc' : 'candle';
    const rawCount = params['count'], rawCount2 = params['count2'], rawOffset = params['offset'];
    const count = typeof rawCount === 'number' && Number.isFinite(rawCount) ? Math.max(4, Math.min(10, Math.round(rawCount))) : 6;
    const count2 = typeof rawCount2 === 'number' && Number.isFinite(rawCount2) ? Math.max(3, Math.min(10, Math.round(rawCount2))) : 6;
    const offset = typeof rawOffset === 'number' && Number.isFinite(rawOffset) ? Math.max(5, Math.min(100, Math.round(rawOffset))) : 80;
    const bull = typeof params['bull'] === 'string' ? params['bull'] : '#73c3e1';
    const bear = typeof params['bear'] === 'string' ? params['bear'] : '#ffc0b2';
    const wick = typeof params['wick'] === 'string' ? params['wick'] : '#ffffff';
    const labelColor = typeof params['labelColor'] === 'string' ? params['labelColor'] : '#ffffff';
    const label = params['label'] === true;
    const ohlcLabel = params['ohlcLabel'] !== false;
    const orderflow = params['orderflow'] !== false;
    const neutral = typeof params['neutral'] === 'string' ? params['neutral'] : '#9e9e9e';
    const chartMs = barSize(series.bars);
    const custom = params['timeframe'];
    const tf: Timeframe = type === 'custom' && typeof custom === 'string' && isTimeframe(custom) ? custom : autoTimeframe(chartMs, type === 'custom' ? 'htf-pda' : type);
    const rawSecond = params['second'];
    // Empty or auto is the Pine's own choice, never a fixed `D` (T-1145).
    const second: Timeframe = typeof rawSecond === 'string' && isTimeframe(rawSecond) ? rawSecond : autoSecond(chartMs);
    const lastStart = series.bars[series.bars.length - 1]![0];
    const plots: Plot[] = [];
    // One frame, or two with the dual mode on (T-0044): each at its own offset, oldest first, so a line drawn over another is the newer one.
    // Pine's `drawDC_tf_2` opens with `not(timeframe.isweekly or timeframe.ismonthly)` (`:1111`): on a weekly or monthly chart only the
    // first frame is drawn, whatever the dual mode and the second timeframe say (T-1170).
    const dual = params['dual'] !== false && chartMs < WEEK;
    for (const frame of framePlan(tf, dual, offset, second, count, count2)) {
      // The frame's data is the frame's own series, not the chart's folded: the page holds a few hundred bars, so a monthly frame folded
      // from them yields three candles while the number asks for five (measured: 1500 hourly bars → 3 monthly ones, T-1173). The stretch
      // asked back is what the number needs, which is what the Pine's `request.security` gets for free. Without the series (an older
      // host, a venue with no such interval) the chart is folded as before, so the piece never draws less than it used to.
      const wanted = frame.count + 2, bar = timeframeMs(frame.tf);
      const deep = ctx.data.candles('series:' + frame.tf, wanted * bar)?.bars;
      // The whole aggregation, not just the drawn slice: the oldest drawn candle still has the one before it to be judged against, which
      // is how Pine colours it (the slice only decides how many are drawn).
      const whole = deep !== undefined && deep.length >= 2;
      const all = whole ? framesOf(deep, lastStart) : aggregate(series.bars, frame.tf);
      const groups = all.slice(-frame.count);
      if (!groups.length) continue;
      const first = all.length - groups.length;
      groups.forEach((group, index) => {
        const position = frame.offset + (index + 1) * 3;
        const t0 = lastStart + position * chartMs, t1 = t0 + 2 * chartMs, center = t0 + chartMs;
        // The Pine's rule, the same one its table uses (`:2199`): with `trend_orderflow` on, the frame's bias decides the colour; off,
        // the candle's own body. The bias is `biasState`, the rule `trend-bias` already ports — the same one the high/low marks read.
        const body = group.close > group.open ? bull : bear;
        const biasHere = orderflow ? biasOfFrame(all, first + index) : null;
        // The frame before the first one held has nothing to be compared with: it keeps its body colour, as the Pine's white default does.
        const color = !orderflow || biasHere === null ? body
          : biasHere === 'bullish' || biasHere === 'pre-bullish' ? bull
            : biasHere === 'bearish' || biasHere === 'pre-bearish' ? bear
              : neutral;
        if (style === 'candle') {
          plots.push({ kind: 'line', points: [{ t: center, p: group.high }, { t: center, p: group.low }], style: { width: 1, color: wick } });
          plots.push({ kind: 'box', t0, t1, p0: Math.min(group.open, group.close), p1: Math.max(group.open, group.close), color });
          return;
        }
        // OHLC: the high-low bar with the open and the close ticked either side and named, as `drawDC_tf_1` does with box borders and 'A'/'C'.
        const half = chartMs * 0.4;
        plots.push({ kind: 'line', points: [{ t: center, p: group.high }, { t: center, p: group.low }], style: { width: 1, color } });
        plots.push({ kind: 'line', points: [{ t: center - half, p: group.open }, { t: center + half, p: group.open }], style: { width: 1, color } });
        plots.push({ kind: 'line', points: [{ t: center - half, p: group.close }, { t: center + half, p: group.close }], style: { width: 1, color } });
        if (ohlcLabel) {
          // The Pine's letters (`:1000`, `:1069-1079`), not O/C: `A` on the open, and the high and the low named by the body's direction —
          // `D` over the high and `M` under the low when the candle closed up, the other way round when it closed down (T-1172).
          const up = group.close > group.open;
          plots.push({ kind: 'label', t: center + half, p: group.open, text: 'A', color: labelColor });
          plots.push({ kind: 'label', t: center, p: group.high, text: up ? 'D' : 'M', color: labelColor });
          plots.push({ kind: 'label', t: center, p: group.low, text: up ? 'M' : 'D', color: labelColor });
        }
      });
      if (label) {
        const oldest = groups[0]!;
        // The Pine's box says what it is above the frame (`'TF\n' + tf_text`, `:1093`), two lines, and the painter stacks them (T-1172).
        plots.push({ kind: 'label', t: lastStart + (frame.offset + 3) * chartMs, p: oldest.high, text: `TF\n${TIMEFRAME_NAMES[frame.tf]}`, color: labelColor });
      }
    }
    // The frames were placed past the last bar; how much of that the person can see is the view's business (T-1149).
    return plots.length ? { plots: withinView(plots, ctx.view.t1, chartMs) } : null;
  },
};
