import { el } from './dom.ts';
import { t } from './i18n.ts';
import { button, heading, note, selectRow } from './ui.ts';
import { PALETTES, registerPalette, resolveThemeId } from './theme.ts';
import type { Store } from './store.ts';
import {
  CUSTOM_TOKEN_IDS, MAX_CUSTOM_THEMES, customPalette, contrastWarnings, isHex, themeIdFor, tokensOfPalette, uniqueThemeId,
  type CustomTheme, type CustomToken,
} from './custom-themes.ts';

/** The id the editor paints while a colour is being chosen: registered like a saved theme, never written into the state. */
const PREVIEW_ID = 'custom:preview';

/** A token's word, asked with literals so the eleven packs carry every one of them. */
function tokenLabel(id: CustomToken): string {
  switch (id) {
    case 'bg': return t('Background');
    case 'panel': return t('Panel');
    case 'line': return t('Line');
    case 'text': return t('Text');
    case 'muted': return t('Muted');
    case 'accent': return t('Accent');
    case 'ui': return t('Focus');
    case 'bid': return t('Buy');
    case 'ask': return t('Sell');
    case 'poc': return t('POC');
    case 'level': return t('Level');
    case 'vwap': return t('VWAP');
  }
}
const surfaceLabel = (id: 'bg' | 'panel'): string => id === 'bg' ? t('Background') : t('Panel');

/**
 * The theme editor (T-1319): a theme of one's own, by name, over one of the box's palettes. Choosing a colour paints the page at once through
 * the menu's own preview path (`onPreview`, the same one a hovered theme uses), so what is seen is what will be kept; Save writes it, and the
 * page's save and the exported layouts carry it from there. The contrast line **warns** — the pairs below AA, with their numbers — and never
 * blocks: the box's own light palette does not pass as text either (`--ui` 3.41, `--bid`/`--ask` 3.00).
 */
export function buildThemeEditor(store: Store, body: HTMLElement, onPreview: (id: string | null) => void, rebuild: () => void): void {
  const state = store.state;
  const customs = state.customThemes;
  const active = customs.find(theme => theme.id === state.theme) ?? null;
  // A new theme starts from the page as it is; one of its own starts as it was saved.
  const base = active?.base ?? resolveThemeId(state.theme);
  const draft: CustomTheme = active
    ? { id: active.id, name: active.name, base: active.base, tokens: { ...active.tokens } }
    : { id: '', name: '', base, tokens: tokensOfPalette(PALETTES[base]!) };
  let name = draft.name;
  let editingId = draft.id;

  const paint = (): void => {
    const palette = customPalette({ ...draft, name: name || t('Custom theme'), base: draft.base });
    if (!palette) return;
    registerPalette(PREVIEW_ID, palette);
    onPreview(PREVIEW_ID);
  };

  const nameRow = (): HTMLElement => {
    const input = el('input', { type: 'text', value: name, maxLength: 40, placeholder: t('Name of the theme'), ariaLabel: t('Name of the theme') });
    input.oninput = () => { name = input.value; };
    return el('label', { class: 'field' }, el('span', { class: 'label' }, el('span', { class: 'name', textContent: t('Name') })), input);
  };

  const tokenRow = (id: CustomToken): HTMLElement => {
    const box = el('input', { type: 'color', value: draft.tokens[id], ariaLabel: tokenLabel(id) });
    const hex = el('span', { class: 'desc', textContent: draft.tokens[id] });
    box.oninput = () => {
      if (!isHex(box.value)) return;
      draft.tokens[id] = box.value;
      hex.textContent = box.value;
      paint();
      drawContrast();
    };
    return el('label', { class: 'field' }, el('span', { class: 'label' }, el('span', { class: 'name', textContent: tokenLabel(id) }), hex), box);
  };

  const contrastBox = el('div', { class: 'theme-contrast' });
  const drawContrast = (): void => {
    const warnings = contrastWarnings(draft.tokens);
    if (!warnings.length) { contrastBox.replaceChildren(note(t('Contrast: every pair passes AA.'))); return; }
    contrastBox.replaceChildren(
      ...warnings.map(w => el('p', { class: 'panel-note', textContent: t('Contrast: {pair} is {ratio}:1, below {need}:1.', { pair: `${tokenLabel(w.token)} / ${surfaceLabel(w.surface)}`, ratio: w.ratio.toFixed(2), need: String(w.need) }) })),
      note(t('It is saved anyway: this only warns.')),
    );
  };

  const save = (): void => {
    const clean = name.replace(/\s+/g, ' ').trim().slice(0, 40).trim();
    if (!clean) return;
    const id = editingId || uniqueThemeId(customs, clean);
    const theme: CustomTheme = { id, name: clean, base: draft.base, tokens: { ...draft.tokens } };
    const next = customs.some(x => x.id === id) ? customs.map(x => x.id === id ? theme : x) : [...customs, theme].slice(0, MAX_CUSTOM_THEMES);
    // Register first, so the page paints the theme in the same change that chooses it.
    registerPalette(id, themePalette(theme));
    store.set({ customThemes: next, theme: id, themePicked: true });
    editingId = id;
    rebuild();
  };

  const remove = (): void => {
    if (!editingId) return;
    const next = customs.filter(theme => theme.id !== editingId);
    store.set({ customThemes: next, theme: draft.base });
    onPreview(null);
    rebuild();
  };

  // The list chooses which of the person's own themes is being edited; a new one is made by choosing its base in the theme menu and saving it
  // here under a name of its own, which is what "one theme of mine, by name" means without a second door.
  const picker = customs.length
    ? selectRow(t('Own themes'), '', customs.map(theme => [theme.id, theme.name] as [string, string]), active?.id ?? customs[0]!.id, id => {
      store.set({ theme: id, themePicked: true });
      rebuild();
    })
    : note(t('No theme of your own yet: choose its colours and press Save.'));

  body.append(
    picker,
    nameRow(),
    heading(t('Colours')),
    ...CUSTOM_TOKEN_IDS.map(tokenRow),
    contrastBox,
    el('div', { class: 'panel-actions' },
      button(t('Save'), save),
      button(t('Delete this theme'), remove),
      button(t('Cancel'), () => { onPreview(null); rebuild(); }, '', 'theme-cancel')),
    note(t('A theme of your own is kept in this browser and travels in the layouts you export.')),
  );
  drawContrast();
  paint();
  // Leaving the editor without saving puts the page back as it was.
  window.setTimeout(() => { const panel = body.closest('.panel'); panel?.querySelector('.panel-close, .panel-x')?.addEventListener('click', () => onPreview(null), { once: true }); }, 0);
}

/** The palette a saved theme draws, for the caller that registers it (the editor's own; the page uses `registerCustomThemes`). */
function themePalette(theme: CustomTheme) {
  return customPalette(theme) ?? PALETTES[resolveThemeId(theme.base)]!;
}

/** The id a new theme would take for a name, exposed for the acceptance test that reads ids. */
export const themeIdOf = (name: string): string => themeIdFor(name);
