import { BEAR_WINDOWS, BULL_WINDOWS, inCycleWindow } from '../../indicators/range-pressure.ts';

/**
 * El **barrido** del nivel HTF 2 de Previous OHLC (T-1246), portado de `OddEyeCircle:1689-1697`:
 *
 * - bajista: el **high de HTF 1 perfora** el cierre previo de HTF 2 y el **cierre vuelve por debajo** (`:1689`);
 * - alcista: el **low de HTF 1 perfora** y el **cierre vuelve por encima** (`:1690`);
 * - el resaltado y las marcas sólo se pintan en su ciclo (`:1692-1695`): alcistas en **A/M**, bajistas en **D/X**, las mismas ventanas que
 *   usa Pressure (`BULL_WINDOWS` / `BEAR_WINDOWS`, `range-pressure.ts:176-177`), no una copia de la lista.
 *
 * El estilo es el del Pine (`:150`, `:1679-1680`) con su tercer valor: `fill`, `markers` y `both` — el «Combinado» del usuario, que en el Pine
 * se llama `Fill + Markers` y **existe allí** (leído en `origin/main`, no en el árbol de trabajo del oráculo, que está viejo). Lo único que
 * se aparta del Pine es el **default**: `both`, decidido por el usuario, donde el Pine abre en `Fill`. Va en `Notas:`.
 *
 * Puro y sin DOM: el pintor (`paint.ts`) sólo pregunta y dibuja.
 */

/** Los tres valores de `keylevels_plot_style` (`OddEyeCircle:150`). */
export type SweepStyle = 'fill' | 'markers' | 'both';

/** Qué dibuja cada estilo (`OddEyeCircle:1679-1680`). */
export function sweepStylePaints(style: SweepStyle): { readonly fill: boolean; readonly markers: boolean } {
  return { fill: style === 'fill' || style === 'both', markers: style === 'markers' || style === 'both' };
}

/** La vela de HTF 1 que barre, y el cierre previo de HTF 2 contra el que se compara (`:1689-1690`). */
export interface SweepBars {
  readonly high: number;
  readonly low: number;
  readonly close: number;
  /** `prevClose_candle_2`: el cierre del periodo anterior de HTF 2. */
  readonly level: number;
}

/** El barrido en sí, sin ciclo: las dos condiciones del Pine, tal cual. */
export function sweepOf(bars: SweepBars): { readonly bull: boolean; readonly bear: boolean } {
  return {
    bear: bars.high > bars.level && bars.close < bars.level,
    bull: bars.low < bars.level && bars.close > bars.level,
  };
}

/** El barrido ya pasado por su ciclo (`:1692-1695`). Va **fijo**, como en el Pine: no hay interruptor (decisión del Chief, 2026-11-23). */
export interface SweepState {
  readonly bull: boolean;
  readonly bear: boolean;
  /** Alcista en A/M (`htf2_sweep_bull_ok`). */
  readonly bullOk: boolean;
  /** Bajista en D/X (`htf2_sweep_bear_ok`). */
  readonly bearOk: boolean;
}

export function sweepState(bars: SweepBars, t: number): SweepState {
  const { bull, bear } = sweepOf(bars);
  return { bull, bear, bullOk: bull && inCycleWindow(t, BULL_WINDOWS), bearOk: bear && inCycleWindow(t, BEAR_WINDOWS) };
}

/**
 * La marca de un barrido **nuevo**: el Pine exige `and not htf2_sweep_*[1]` (`:1739`), o sea una sola marca por barrido, y la pone en el precio
 * que barrió — el **low de HTF 1** en el alcista y el **high** en el bajista—, nunca en la vela del gráfico.
 */
export interface SweepMarks {
  readonly bull: number | null;
  readonly bear: number | null;
}

export function sweepMarks(now: SweepState, before: { readonly bull: boolean; readonly bear: boolean }, bars: SweepBars): SweepMarks {
  return {
    bull: now.bullOk && now.bull && !before.bull ? bars.low : null,
    bear: now.bearOk && now.bear && !before.bear ? bars.high : null,
  };
}

/** El alpha del relleno (`:1696-1697`): 30 cuando hay barrido en su ciclo, 100 cuando no. */
export function sweepFillAlpha(state: SweepState): number {
  return state.bullOk || state.bearOk ? 30 : 100;
}

/** Una barra de HTF 1, en el tiempo del gráfico. */
export interface SweepBar {
  readonly t: number;
  readonly high: number;
  readonly low: number;
  readonly close: number;
}

/** El área que el Pine rellena (`fill(prefhtf2, ppricehtf2, …)`, `:1692-1697`): de la barra al nivel, con el alpha del barrido. */
export interface SweepBand {
  readonly t0: number;
  readonly t1: number;
  readonly top: number;
  readonly bottom: number;
  readonly side: 'bull' | 'bear';
  readonly alpha: number;
}

/** Una marca del barrido, en su precio y su tiempo (`plot(htf2_sweep_*_mark, …, linewidth = 4)`, `:1739`). */
export interface SweepMark {
  readonly t: number;
  readonly price: number;
  readonly side: 'bull' | 'bear';
}

/**
 * Las áreas y las marcas de una serie de HTF 1 contra el cierre previo de HTF 2 (`level`). Puro: el pintor sólo dibuja lo que sale de aquí.
 *
 * Una marca por barrido (no por barra): el Pine exige que la condición no estuviera puesta en la barra anterior (`and not htf2_sweep_*[1]`). El
 * área, en cambio, se pinta en **cada** barra donde el barrido sigue vivo, que es lo que hace el `fill()` con una serie de precios.
 */
export function sweepBands(bars: readonly SweepBar[], level: number, barMs: number): { bands: SweepBand[]; marks: SweepMark[] } {
  const bands: SweepBand[] = [];
  const marks: SweepMark[] = [];
  let before = { bull: false, bear: false };
  for (const bar of bars) {
    const state = sweepState({ high: bar.high, low: bar.low, close: bar.close, level }, bar.t);
    const alpha = sweepFillAlpha(state);
    if (state.bullOk) bands.push({ t0: bar.t, t1: bar.t + barMs, top: level, bottom: bar.low, side: 'bull', alpha });
    if (state.bearOk) bands.push({ t0: bar.t, t1: bar.t + barMs, top: bar.high, bottom: level, side: 'bear', alpha });
    const mark = sweepMarks(state, before, { high: bar.high, low: bar.low, close: bar.close, level });
    if (mark.bull !== null) marks.push({ t: bar.t, price: mark.bull, side: 'bull' });
    if (mark.bear !== null) marks.push({ t: bar.t, price: mark.bear, side: 'bear' });
    before = { bull: state.bull, bear: state.bear };
  }
  return { bands, marks };
}
