import { el } from './dom.ts';

/**
 * The one shape the panels share that is **not** the inspector: a **list row** (T-1099), with its name as the data it is, an optional second
 * line and an optional button to remove it. The other two shapes this module used to hold — `band` and `rowsOnSurface`, the boxed panel of
 * T-1091/T-1098 — have no caller since the inspector (`inspector.ts`) replaced them in every panel (T-1245), and they are gone: a function
 * kept alive only by its test is a function that comes back with its bug (the `NotFoundError` of T-1244) and nobody calls it.
 */
/**
 * A row that is not a setting (T-1099, decided with Designer): a **list** row, with its name as the data it is, an optional second line and
 * an optional button to remove it. The name is never translated here — it is a session's own name or an anchor's date, not a word of the
 * interface — and the button's `label` is, so the panel that knows the case writes it. A row that needs a switch, a select or a disabled
 * state is not a list: it is a control row and goes through `switchRow` / `selectRow`, so this function never grows towards that.
 */
export interface ListRow {
  /** The data the row names, exactly as it is: never a key of the page's words. */
  readonly name: string;
  /** A second line: a zone and its hours, a price and a date. */
  readonly detail?: string;
  /** The button that takes it out of the list; the label is the panel's (translated), and a read-only list leaves it out. */
  readonly remove?: { readonly label: string; readonly onRemove: () => void };
}

export function listRow(row: ListRow): HTMLElement {
  const line = el('div', { class: 'tb-row tb-list' });
  line.style.gridTemplateColumns = '1fr auto';
  line.append(el('span', { class: 'tb-list-text' },
    el('span', { class: 'name', textContent: row.name }),
    ...(row.detail ? [el('span', { class: 'desc', textContent: row.detail })] : [])));
  if (row.remove) line.append(el('button', { type: 'button', class: 'session-remove', ariaLabel: row.remove.label, onclick: row.remove.onRemove }));
  return line;
}
