/** Assign a form control's value only when it differs: assigning to an open select closes its popup. */
function setValue(control: HTMLSelectElement | HTMLInputElement, value: string): void { if (control.value !== value) control.value = value; }

/** Light or dim a button's lamp (`.led-btn`): it says whether the feature the button opens is on. Written only when it changes. */
function lamp(button: HTMLElement, on: boolean): void { const state = on ? 'on' : 'off'; if (button.dataset.state !== state) button.dataset.state = state; }

/**
 * A split button (Karl, 2026-10-17): `main` switches its feature on or off in one click and its lamp says which; the small key joined to its
 * right, with drawn sliders, opens the feature's settings. The pair is one element, so the deck and the phone's Settings lay it out whole.
 */
function splitButton(main: HTMLButtonElement, key: HTMLButtonElement): HTMLElement { return el('span', { class: 'split' }, main, key); }
/** The Key levels split, marked so the glass material can find it (it lives in a deck, not on the map). */
const keyLevelsSplit = (main: HTMLButtonElement, key: HTMLButtonElement): HTMLElement => el('span', { class: 'split split-keylevels' }, main, key);

/** The settings key of a split button, named for its feature (`Settings: VWAP`) for a tooltip and a screen reader. */
function settingsKey(name: string): HTMLButtonElement {
  const label = `${t('Settings')}: ${name}`;
  return el('button', { type: 'button', class: 'split-cfg', ariaLabel: label, tip: label });
}

/**
 * One deck of the full top bar: a group of up to two rows of controls, named by a word in small capitals before them
 * (T-1252, A — instrument). It was a `fieldset` whose `legend` sat in the frame line; with the frame gone there is
 * nothing for a legend to sit in, and a legend cannot share its content's line without `float`, which no `flex`
 * parent promises the same way in every frame. The name is a `span` and it is still what moves the group.
 */
function deck(id: string, title: string, ...rows: HTMLElement[][]): HTMLElement {
  const name = el('span', { class: 'deck-name', textContent: title });
  name.title = t('Drag to move this group. The bar wraps its groups to fit the window.');
  const field = el('div', { class: `deck deck-${id}` }, name,
    ...rows.filter(r => r.length).map(r => el('div', { class: 'deck-row' }, ...r)));
  field.dataset.deck = id;
  // The fieldset named its group with its legend; a div has to say it, so a reader still hears what the group is.
  field.setAttribute('role', 'group');
  field.setAttribute('aria-label', title);
  return field;
}

/** Top bar: market (coin, market, timeframe, spot / perp), the pane toggles, the chart's features, the alerts, and the page's own. */

/** The material's three names as a select (T-1089), the bar's and a phone's sharing one look. */
function materialSelect(): HTMLSelectElement {
  const select = el('select', { class: 'material-select', ariaLabel: t('Material'), tip: t('Material: solid, bubble or liquid glass.') });
  for (const value of ['solid', 'bubble', 'liquid'] as const) select.append(el('option', { value, textContent: value === 'solid' ? t('Solid') : value === 'bubble' ? t('Bubble') : t('Liquid') }));
  return select;
}
/** A select's value as the store's material: anything else is the frosted glass, never a crash. */
function materialOf(value: string): 'solid' | 'bubble' | 'liquid' { return value === 'solid' || value === 'liquid' ? value : 'bubble'; }

