    this.#heatSplit = splitButton(this.#heatButton, this.#heatKey); this.#tpoButton.onclick = () => { this.store.set({ tpo: { ...this.store.state.tpo, on: !this.store.state.tpo.on } }); this.refreshOpenPanel(); }; this.#tpoKey.onclick = () => { const build = (tools: HTMLElement, body: HTMLElement): void => buildTpoPanel(this.store, tools, body, () => this.#tpoPanel?.render(build), this.tpoInfo); this.#tpoPanel = this.#track(togglePanel(this.#tpoKey, { title: t('TPO'), width: 440, align: 'left', help: helpButton('tpo'), onClose: () => { this.#tpoPanel = null; } }, build), build); }; this.#tpoSplit = splitButton(this.#tpoButton, this.#tpoKey);
    this.#scriptsSplit = splitButton(this.#scripts, this.#scriptsKey);
