import { el } from './dom.ts';
import { isCoarse } from './device.ts';
import { t } from './i18n.ts';
import { wallClock, cycleAgenda, cycleAt, cycleShare, CYCLE_SESSIONS, CYCLE_90_ZONE, type CycleGroup } from '../indicators/cycle-90.ts';
import { countdownText, nextClose } from '../indicators/trend-bias.ts';
import type { ReadoutRow } from '../engine/studies/contract.ts';
import type { Timeframe } from '../engine/time/timeframe.ts';

/**
 * The work bar: the row along the bottom of a desktop page (T-1298, mockup `docs/platform/mockups/barra-trabajo-1440.png`). Three zones, one
 * line: the market the chart reads (the controls the top bar's Market deck used to carry), the trend bias of every frame as one row of cells,
 * and the 90-minute cycle as a pill with its ring and its countdown, whose press opens the cycles that come next.
 *
 * It computes nothing. The bias is the `readout` of the `trend-bias` piece and the cycle the one of `cycle-90` (D-31): the bar reads the
 * numbers the pieces published, and counts down with the clock, so a second of this bar is a text write and never a second calculation.
 */

/** A side as the piece publishes it, or `null` while its series has not arrived. */
type BiasSide = 'bullish' | 'bearish' | 'pre-bullish' | 'pre-bearish' | 'neutral';

/** One cell of the bias row: the family's frame and its countdown, or an `Actual` frame and its side. */
export interface BiasCell {
  readonly id: string;
  /** The frame, `5m` / `D` / `Actual D`. */
  readonly frame: string;
  /** The second line: the countdown of a family frame, the side's word of an `Actual` one. */
  readonly line: string;
  readonly side: BiasSide | null;
  /** Whether the cell is one of the `Actual` group (no countdown). */
  readonly actual: boolean;
  /** The colour of its 2 px bar when the piece names one (T-1324, orderflow off); empty means the side's own tone, painted by CSS. */
  readonly fill: string;
}

const SIDES: readonly BiasSide[] = ['bullish', 'bearish', 'pre-bullish', 'pre-bearish', 'neutral'];

const valuesOf = (row: ReadoutRow): Map<string, number | string | boolean> => new Map(row.values.map(value => [value.id, value.value]));

const sideOf = (value: number | string | boolean | undefined): BiasSide | null =>
  typeof value === 'string' && (SIDES as readonly string[]).includes(value) ? value as BiasSide : null;

/** The side's word, as the panels say it (the piece publishes the code, the app the word). */
export function sideWord(side: BiasSide | null): string {
  switch (side) {
    case 'bullish': return t('Bullish');
    case 'bearish': return t('Bearish');
    case 'pre-bullish': return t('Pre-Bullish');
    case 'pre-bearish': return t('Pre-Bearish');
    case 'neutral': return t('Neutral');
    default: return t('No data');
  }
}

/**
 * The bias row, from the piece's own readout: one cell a frame of the family (`bias:<tf>`) and one a frame of the `Actual` group
 * (`actual:<n>`), in the piece's order. The countdown is worked out here from the frame and the clock (`nextClose`), never read from a
 * snapshot, so the row keeps counting between two passes of the map.
 */
export function biasCells(rows: readonly ReadoutRow[], now: number): BiasCell[] {
  const out: BiasCell[] = [];
  for (const row of rows) {
    const values = valuesOf(row), side = sideOf(values.get('bias'));
    if (row.id.startsWith('bias:')) {
      const tf = row.id.slice('bias:'.length) as Timeframe;
      const frame = String(values.get('tf') ?? row.label);
      // The counter's own switch (T-1324): off, the frame stays and the line goes.
      out.push({ id: row.id, frame, line: values.get('counter') === 'off' ? '' : countdownText(now, nextClose(now, tf), tf) || '—', side, actual: false, fill: String(values.get('fill') ?? '') });
    } else if (row.id.startsWith('actual:')) {
      out.push({ id: row.id, frame: row.label, line: sideWord(side), side, actual: true, fill: String(values.get('fill') ?? '') });
    }
  }
  return out;
}

/** The cycle in course, read from `cycle-90`'s row and counted with the clock. */
export interface CycleNow {
  readonly label: string;
  /** The group the window belongs to (`cycle-90`'s own `group`), for the flag inside the ring. */
  readonly group: CycleGroup;
  readonly tone: 'up' | 'dn';
  readonly from: number;
  readonly to: number;
  readonly leftMs: number;
  readonly share: number;
  /** What the pill prints (T-1313): its wall clock and the countdown, each the piece's own switch and neither the piece's drawing. */
  readonly clock: boolean;
  readonly countdown: boolean;
}

export function cycleNow(rows: readonly ReadoutRow[], now: number): CycleNow | null {
  const row = rows.find(candidate => candidate.id === 'cycle:now');
  if (row) {
    const values = valuesOf(row), from = Number(values.get('from')), to = Number(values.get('to')), tone = values.get('tone') === 'dn' ? 'dn' : 'up';
    const group = values.get('group');
    if (Number.isFinite(from) && Number.isFinite(to) && to > from && (group === 'asia' || group === 'london' || group === 'nyam' || group === 'nypm')) {
      return {
        label: String(values.get('label') ?? row.label), group, tone, from, to,
        leftMs: Math.max(0, to - now), share: Math.min(1, Math.max(0, (now - from) / (to - from))),
        clock: values.get('clock') !== false, countdown: values.get('countdown') !== false,
      };
    }
  }
  // The piece publishes only while it is switched on and drawing (its pin and its own timeframe gate): the row must still say which
  // cycle the clock is inside, so it asks the piece's own function for it, never a second grid of its own.
  const cycle = cycleAt(now);
  return cycle ? { label: cycle.label, group: cycle.group, tone: cycle.tone, from: cycle.from, to: cycle.to, leftMs: cycle.leftMs, share: cycleShare(cycle, now), clock: true, countdown: true } : null;
}

/** "34m", "3h 34m": what is left of a window, at the size the row shows it. */
export function shortLeft(ms: number): string {
  const minutes = Math.max(0, Math.round(ms / 60_000));
  return minutes >= 60 ? t('{h}h {m}m', { h: Math.floor(minutes / 60), m: minutes % 60 }) : t('{m}m', { m: minutes });
}

/** The zone's clock reading of an instant, as the cycle list writes a window: `20:30`. */
const at = (ms: number): string => { const wall = wallClock(ms, CYCLE_90_ZONE); return `${String(wall.hh).padStart(2, '0')}:${String(wall.mm).padStart(2, '0')}`; };

// The Pine names the groups in English; the row shows the page's words for them, the same the pieces' panels use.
const GROUP_WORD: Readonly<Record<CycleGroup, string>> = { asia: t('Asia'), london: t('London'), nyam: t('NY AM'), nypm: t('NY PM') };
/** The flag of each group's market, inside the ring that fills (the user's image, T-1312): one group, one country's mark. */
const GROUP_FLAG: Readonly<Record<CycleGroup, string>> = { asia: '🇯🇵', london: '🇬🇧', nyam: '🇺🇸', nypm: '🇺🇸' };

/**
 * Whether the list opens by itself over the cycle: a pointer that hovers and is not a finger. A phone has no hover, and there the tap keeps the
 * list the click opened until this card (T-1312). Exported so the rule is held by a test rather than by a `matchMedia` nobody can read.
 */
export const cycleHoverOpens = (coarse: boolean, hover: boolean): boolean => !coarse && hover;
/** How long the pointer must rest on the cycle before the list opens: long enough not to fire on the way past it (T-1312). */
export const CYCLE_HOVER_MS = 120;
/** How long the list waits after the pointer leaves the pill: enough to cross the gap up to its gear, short enough not to linger (T-1324). */
export const CYCLE_HOVER_CLOSE_MS = 240;

/** A ring drawn as one arc: what has run of the window in the side's own tone (the mockup's gauge). */
function ring(size: number, share: number, tone: 'up' | 'dn' | null): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`); svg.setAttribute('width', String(size)); svg.setAttribute('height', String(size));
  svg.setAttribute('aria-hidden', 'true');
  const stroke = size / 9, r = (size - stroke) / 2, c = 2 * Math.PI * r;
  for (const [cls, covered] of [['wb-ring-track', 1], ['wb-ring-arc', Math.min(1, Math.max(0, share))]] as const) {
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('cx', String(size / 2)); circle.setAttribute('cy', String(size / 2)); circle.setAttribute('r', String(r));
    circle.setAttribute('fill', 'none'); circle.setAttribute('stroke-width', String(stroke));
    circle.setAttribute('stroke-dasharray', String(c * covered) + ' ' + String(c));
    circle.setAttribute('transform', `rotate(-90 ${size / 2} ${size / 2})`);
    circle.setAttribute('class', cls);
    svg.append(circle);
  }
  svg.dataset.tone = tone ?? 'none';
  return svg;
}

/** The four arcs of the cycle ring: one per window of the Pine's grid, in the piece's own colour. */
function groupRing(size: number, now: number): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`); svg.setAttribute('width', String(size)); svg.setAttribute('height', String(size));
  svg.setAttribute('aria-hidden', 'true');
  const stroke = size / 7, r = (size - stroke) / 2, c = 2 * Math.PI * r;
  // The Pine's grid walked in order: each window is one arc, the bars between two of them stay the track.
  for (const spec of CYCLE_SESSIONS) {
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    const span = (spec.endMin - spec.startMin) / 1440;
    circle.setAttribute('cx', String(size / 2)); circle.setAttribute('cy', String(size / 2)); circle.setAttribute('r', String(r));
    circle.setAttribute('fill', 'none'); circle.setAttribute('stroke-width', String(stroke)); circle.setAttribute('stroke', spec.color);
    circle.setAttribute('stroke-dasharray', `${c * span} ${c}`);
    circle.setAttribute('stroke-dashoffset', String(-c * (spec.startMin / 1440)));
    circle.setAttribute('transform', `rotate(-90 ${size / 2} ${size / 2})`);
    svg.append(circle);
  }
  return svg;
}

export class WorkBar {
  readonly root = el('div', { class: 'workbar', role: 'group' });
  /** Where the market controls go: the toolbar fills it on a desktop (the Market deck is gone; T-1298). */
  readonly market = el('div', { class: 'wb-market' });
  /** Whether the data is flowing: the photo of the status line the row used to be its own (T-1298). */
  readonly status = el('span', { class: 'wb-status' });
  /** The one way into Settings (the gear, and the news dot beside it while there is news). */
  readonly controls = el('span', { class: 'wb-controls' });
  #cells = el('div', { class: 'wb-cells' });
  /**
   * Only the word is the door (T-1330): it opens the piece's settings, and the frames beside it are a reading that answers no press.
   * T-1328 had made the whole zone one button, so a press on a figure opened a window it does not set; the user asked for the word alone.
   */
  #biasZone = el('div', { class: 'wb-bias' });
  #biasButton = el('button', { type: 'button', class: 'wb-bias-label', ariaLabel: t('Trend bias of every frame') });
  #cycle = el('button', { type: 'button', class: 'wb-cycle', ariaLabel: t('The 90 minute cycle in course') });
  #cycleRing = el('span', { class: 'wb-ring' });
  #cycleWrap = el('span', { class: 'wb-cycle-wrap' });
  /** What the page gives the widget: the piece's switch and its panel. Nothing here knows about studies. */
  #togglePiece: () => void = () => undefined;
  #openSettings: () => void = () => undefined;
  #openBias: () => void = () => undefined;
  /** The wait between the pointer leaving the pill and the list closing, long enough to cross the gap to the gear (T-1324). */
  #hoverClose = 0;
  /** The pointer is resting on the cycle: only then does a click on the list's own closing do nothing strange. */
  #hoverTimer = 0;
  #openedByHover = false;
  #cycleLabel = el('b');
  #cycleLeft = el('i');
  #pop = el('div', { class: 'wb-pop', hidden: true });
  #written = new Map<Element, string>();
  /** What the last pass of the map published, read through the page's own door (never recomputed here). */
  #readout: (id: string) => readonly ReadoutRow[] = () => [];
  #signature = '';
  #cycleKey = '';

  constructor() {
    this.#cycle.append(this.#cycleRing, el('span', { class: 'wb-cycle-text' }, this.#cycleLabel, this.#cycleLeft));
    this.#cycleWrap.append(this.#cycle);
    this.root.append(this.status, this.market, el('span', { class: 'wb-sep', ariaHidden: 'true' }),
      this.#biasZone,
      el('span', { class: 'wb-spacer' }), this.#cycleWrap, this.controls, this.#pop);
    // The click is the switch of the piece (T-1312); a finger, which has no hover, keeps the list on its tap.
    this.#cycle.onclick = () => { if (isCoarse()) this.#showPop(); else this.#togglePiece(); };
    // The hover opens the list after a rest, and closes it on the way out: it never takes the focus, and a click never opens it (T-1312).
    this.#cycle.addEventListener('pointerenter', () => {
      if (!cycleHoverOpens(isCoarse(), typeof matchMedia === 'function' && matchMedia('(hover: hover)').matches)) return;
      window.clearTimeout(this.#hoverTimer);
      this.#hoverTimer = window.setTimeout(() => { this.#openedByHover = true; this.#showPop(); }, CYCLE_HOVER_MS);
    });
    // Moving from the pill up to the list crosses a gap, and the list holds the gear: the leave waits a beat, and entering the list calls it
    // off. Closing on the pill's edge left the gear unreachable with the pointer (T-1324, the user).
    this.#cycle.addEventListener('pointerleave', () => {
      window.clearTimeout(this.#hoverTimer);
      if (!this.#openedByHover) return;
      window.clearTimeout(this.#hoverClose);
      this.#hoverClose = window.setTimeout(() => { this.#openedByHover = false; this.#hidePop(); }, CYCLE_HOVER_CLOSE_MS);
    });
    this.#pop.addEventListener('pointerenter', () => { window.clearTimeout(this.#hoverClose); });
    this.#pop.addEventListener('pointerleave', () => {
      window.clearTimeout(this.#hoverClose);
      if (this.#openedByHover) { this.#openedByHover = false; this.#hidePop(); }
    });
    // The word is the door to the piece's own settings (T-1324, T-1330): the deck's button is gone, and the frames are read, not pressed.
    this.#biasButton.append(el('span', { class: 'wb-label', textContent: t('Bias') }));
    this.#biasZone.append(this.#biasButton, this.#cells);
    this.#biasButton.onclick = () => this.#openBias();
    // A press anywhere else closes the list, as every menu of the page does.
    document.addEventListener('pointerdown', event => { if (!this.#pop.hidden && !this.root.contains(event.target as Node)) this.#hidePop(); }, true);
  }

  /** The page's door to the pieces' readouts (`studyReadout`), and the bar's clock (the page's own, so a replay is the moment it shows). */
  /** The two things the cycle's widgets do: switch the piece, and open its settings (T-1312). */
  setCycleActions(actions: { toggle: () => void; settings: () => void }): this {
    this.#togglePiece = actions.toggle; this.#openSettings = actions.settings;
    return this;
  }

  /** What a click on the bias opens: the piece's own settings, the same panel the deck's key used to open (T-1324). */
  setBiasSettings(open: () => void): this { this.#openBias = open; return this; }

  setReadout(readout: (id: string) => readonly ReadoutRow[], now: () => number): this {
    this.#readout = readout; this.#now = now;
    return this;
  }
  #now: () => number = () => Date.now();

  /** Rewrite only what changed: this runs on a one-second clock, so a still page pays nothing for it. */
  update(): void {
    const now = this.#now();
    const cells = biasCells(this.#readout('trend-bias'), now);
    const signature = cells.map(cell => `${cell.id}|${cell.frame}|${cell.line}|${cell.side ?? ''}`).join(';');
    if (signature !== this.#signature) {
      this.#signature = signature;
      // A piece that is off publishes nothing (T-1300: the table is no longer on the map either): the row says so instead of leaving a
      // word with nothing beside it.
      this.#cells.replaceChildren(...(cells.length ? cells.map(cell => this.#cellOf(cell)) : [el('i', { class: 'wb-empty', textContent: t('No data') })]));
      this.#biasButton.dataset.side = cells.find(cell => cell.actual)?.side ?? 'none';
    }
    const cycle = cycleNow(this.#readout('cycle-90'), now);
    const key = cycle ? `${cycle.label}|${cycle.tone}|${cycle.to}|${Math.round(cycle.share * 100)}|${shortLeft(cycle.leftMs)}|${cycle.clock}|${cycle.countdown}` : 'none';
    if (key !== this.#cycleKey) {
      this.#cycleKey = key;
      if (cycle) {
        this.#cycle.dataset.tone = cycle.tone;
        this.#write(this.#cycleLabel, cycle.label);
        // The countdown and the clock are the piece's own switches (T-1313): off, the pill keeps the cycle's name and nothing else.
        this.#write(this.#cycleLeft, cycle.countdown ? shortLeft(cycle.leftMs) : '');
        this.#cycleRing.replaceChildren(ring(22, cycle.share, cycle.tone), el('i', { class: 'wb-ring-flag', textContent: GROUP_FLAG[cycle.group], ariaHidden: 'true' }));
        this.#cycle.hidden = false;
      } else {
        this.#cycle.hidden = true;
      }
    }
    if (!this.#pop.hidden) this.#fillPop(now);
  }

  #cellOf(cell: BiasCell): HTMLElement {
    const node = el('div', { class: 'wb-cell' }, el('b', { textContent: cell.frame }), el('i', { textContent: cell.line }));
    node.dataset.id = cell.id; node.dataset.side = cell.actual ? cell.side ?? 'none' : 'frame';
    if (cell.side) node.dataset.tone = cell.side;
    // The cell's colour is its 2 px bar's, never a fill (T-1324, corrected by the user on 2026-11-26): the piece's own colour when it names one
    // — the three backgrounds, with the orderflow off — and the side's tone otherwise. It goes in a custom property so the sheet paints it and a
    // theme change needs no repaint here.
    if (cell.fill) node.style.setProperty('--cell-fill', cell.fill);
    return node;
  }

  #write(node: Element, text: string): void {
    if (this.#written.get(node) === text) return;
    this.#written.set(node, text);
    node.textContent = text;
  }

  /** The list's own gear: the same door as the one beside the cycle. */
  #gearInPop(): HTMLElement {
    const gear = el('button', { type: 'button', class: 'wb-gear wb-gear-pop', textContent: '⚙', ariaLabel: t('The 90 minute cycle\'s settings') });
    gear.onclick = () => { this.#hidePop(); this.#openSettings(); };
    return gear;
  }

  #togglePop(): void { if (this.#pop.hidden) this.#showPop(); else this.#hidePop(); }
  #hidePop(): void { this.#pop.hidden = true; this.#cycle.classList.remove('open'); }
  #showPop(): void {
    this.#pop.hidden = false; this.#cycle.classList.add('open');
    this.#fillPop(this.#now());
  }

  /** The list: the cycle under way and the opening cycle of each group, never the fifteen (T-1297's measure: the row is four). */
  #fillPop(now: number): void {
    const agenda = cycleAgenda(now, 4);
    const rows = agenda.map(slot => {
      const row = el('div', { class: 'wb-pop-row' });
      row.dataset.group = slot.group;
      // The row's mark is the group's own flag, 16 x 11 as the mockup draws it — not a dot of the group's colour (T-1324, measured).
      const dot = el('i', { class: 'wb-row-flag', textContent: GROUP_FLAG[slot.group], ariaHidden: 'true' });
      const name = el('span', { class: 'wb-pop-name' }, `${GROUP_WORD[slot.group]} · ${slot.variant} `, el('em', { textContent: `${at(slot.from)}–${at(slot.to)}` }));
      const left = slot.active
        ? t('in course · {pct} %', { pct: Math.round(((now - slot.from) / (slot.to - slot.from)) * 100) })
        : t('opens in {left}', { left: shortLeft(slot.from - now) });
      const right = el('span', { class: 'wb-pop-left', textContent: left });
      right.dataset.state = slot.active ? 'now' : 'later';
      row.append(dot, name, right);
      return row;
    });
    const running = agenda.find(slot => slot.active);
    const next = agenda.find(slot => !slot.active);
    const summary = running && next
      ? t('{label}, {pct}% of its window covered. {next} opens in {left}.', {
        label: running.label, pct: Math.round(((now - running.from) / (running.to - running.from)) * 100),
        next: next.label, left: shortLeft(next.from - now),
      })
      : '';
    // The `EST · 21:26` label is gone (T-1312): the zone is read in the ring's colours, and the head's right end is where its gear opens.
    const head = el('div', { class: 'wb-pop-head' }, el('span', { class: 'wb-label', textContent: t('Cycles') }), this.#gearInPop());
    const face = el('div', { class: 'wb-pop-face' }, el('div', { class: 'wb-pop-ring' }), el('div', { class: 'wb-pop-list' }, ...rows));
    const ringNode = face.querySelector('.wb-pop-ring')!;
    ringNode.append(groupRing(76, now), el('span', { class: 'wb-pop-clock', textContent: at(now) }), el('i', { class: 'wb-pop-sub', textContent: GROUP_FLAG[cycleAgenda(now, 1)[0]?.group ?? 'asia'] }));
    this.#pop.replaceChildren(head, face, el('p', { class: 'wb-pop-sum', textContent: summary, hidden: summary === '' }));
  }


}
