import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import type { Bar } from '../engine/series/source.ts';
import { CYCLE_90_ZONE, CYCLE_SESSIONS, cycleSessions, type CycleSession, type CycleVariant, type CycleZone } from './cycle-90.ts';

/**
 * `singularity`: the OEC SINGULARITY piece, chart version (D-18) and per session of the 90-minute cycle (D-19). It is the sister of
 * `reverse-zone` (`src/indicators/reverse-zone.ts`): same shape, another condition.
 *
 * The Pine (`OECLiquidityindicators/OddEyeCircle`): the chart conditions are `isSingularity_Bullish_Condition` (2724) and
 * `isSingularity_Bearish_Condition` (2730), four candles of the chart's own series. The drawing (3564-3704) makes the box on the trigger
 * bar: bullish from `low[1]` (top) to `low[3]` (bottom), bearish from `high[3]` (top) to `high[1]` (bottom) — the levels are copied as they
 * are, including the Pine's order (the conditions do not order high[3] above high[1], so a bearish box may come inverted; the levels still
 * travel exactly as the Pine passes them). The bullish trigger only exists inside the A or M complements (`:3571`); the bearish one inside
 * D or X (`:3630`, and the box at `:3632`).
 *
 * Sessions are not recalculated: `cycleSessions` from `cycle-90` (T-1014) gives the windows of every variant (T-1025). The bullish zone
 * lives in an A or M session and the bearish one in a D or X session (`:3630`), so **both sides are emitted**: the note this piece carried
 * until T-1031 — that D/X were not carried and the bearish zone had to stay off — was false once T-1025 landed, and it kept the bearish
 * half of the product silent.
 *
 * No `SINGULARITY HTF` and no demon boxes (D-18). `compute` is pure and imports no hub, store or fetch; the painter draws the plots.
 *
 * One overlap worth saying: NY AM's D and X windows are the same in the Pine (`cycle_zeusy_nyam_D_time` = `cycle_zeusy_nyam_X_time`,
 * `OddEyeCircle:2669-2670`), so `sessionAt` finds the D one first and NY AM is never reported as X. Nothing is lost: the Pine accepts
 * that window for the zone under either complement (`complement_D or complement_X`, `:3432` / `:3630`), and the *range* there is the D
 * one anyway, because `_Draw_Range` gates both NY AM calls with `cycle_nyam_D` alone (`:3081-3082`) — which is why the Pine's own X
 * label for that group is empty.
 */
export interface ZoneOhlc { readonly o: number; readonly h: number; readonly l: number; readonly c: number }
export type ZoneSide = 'bull' | 'bear';

/** `isSingularity_Bullish_Condition` (`OddEyeCircle:2724`), on the chart's own last four candles. */
export function singularityBullishChart(cur: ZoneOhlc, p1: ZoneOhlc, p2: ZoneOhlc, p3: ZoneOhlc): boolean {
  return cur.c > cur.o && cur.c >= p1.c && cur.c > p2.c && cur.c > p3.c
    && p1.c > p1.o && p1.c > p2.c && p1.c > p3.c && p2.c > p2.o && p2.c > p3.o && p2.l >= p3.l && p2.c > p3.c && p3.c < p3.o;
}

/** `isSingularity_Bearish_Condition` (`OddEyeCircle:2730`). */
export function singularityBearishChart(cur: ZoneOhlc, p1: ZoneOhlc, p2: ZoneOhlc, p3: ZoneOhlc): boolean {
  return cur.c < cur.o && cur.c <= p1.c && cur.c < p2.c && cur.c < p3.c
    && p1.c < p1.o && p1.c < p2.c && p1.c < p3.c && p2.c < p2.o && p2.c < p3.o && p2.h <= p3.h && p2.c < p3.c && p3.c > p3.o;
}

const INPUTS: readonly InputSpec[] = [
  { id: 'bull', kind: 'bool', name: 'Bullish zones', default: true, group: 'Singularity' },
  { id: 'bear', kind: 'bool', name: 'Bearish zones', default: true, group: 'Singularity' },
  // The Pine's own colours (`OEC:480`, `:482`), not the palette's: the box is drawn with `singularity_*_css` and its fill is the same
  // colour at 50 of transparency (`OEC:3571`, `:3632`).
  { id: 'bullColor', kind: 'color', name: 'Bullish', default: '#73c3e1', group: 'Singularity' },
  { id: 'bearColor', kind: 'color', name: 'Bearish', default: '#ffc0b2', group: 'Singularity' },
  // The Pine's own style and its two distances (`OEC:476-478`): 'Future' by default, and the anchored box only in 'Right'.
  { id: 'style', kind: 'string', name: 'Style', default: 'Future', options: ['Right', 'Future'], group: 'Singularity' },
  // `singularity_distancea` (`:331`) has no floor and goes to 500; `singularity_distancer` (`:332`) starts at 5 and goes to 500 (T-1183).
  { id: 'anchor', kind: 'int', name: 'Anchor', default: 30, min: 0, max: 500, group: 'Singularity', active: v => v['style'] === 'Right', inactive: 'Only in the Right style.' },
  { id: 'extend', kind: 'int', name: 'Extend', default: 160, min: 5, max: 500, group: 'Singularity', active: v => v['style'] === 'Right', inactive: 'Only in the Right style.' },
  // `singularity_mode` defaults to 'Present' and `singularity_last` to 5 (`OEC:471-472`): that mode keeps only the newest `last` boxes
  // of each side (`GF:925-928`), and 'Historic' keeps them all.
  { id: 'mode', kind: 'string', name: 'Mode', default: 'Present', options: ['Present', 'Historic'], group: 'Singularity' },
  { id: 'last', kind: 'int', name: 'Last', default: 5, min: 1, max: 50, group: 'Singularity' },
  // `singularity_mitigated` is off by default (`OEC:474`) and that is what **deletes** a crossed zone: `_mitigated == false` is the
  // condition of the Pine's cleaners (`GF:921`, `:955`). Switching it on keeps them, as history. `reverse-zone`'s port reads the same
  // switch the other way round and that is T-1060; this piece copies the Pine's direction, not its sibling's.
  { id: 'mitigated', kind: 'bool', name: 'Mitigation', default: false, group: 'Singularity' },
  // `singularity_alert` (`:336`): the Pine's bell. The product has its own alerts, so the switch is carried and declared, not wired to a sound.
  { id: 'alert', kind: 'bool', name: 'Alert', default: false, group: 'Singularity' },
  // The trigger's four (`:337-340`): `barcolor` paints the chart's own bar when the condition fires. A piece cannot recolour a candle, so the
  // port paints a band behind that bar's high and low in the same colour, and the difference is in `Notas` (T-1183).
  { id: 'trigger', kind: 'bool', name: 'Trigger', default: true, group: 'Singularity' },
  // A colour is a preference, not a plot: it stays editable while `Trigger` is off (T-1205), or the chosen colour could never be set before
  // turning the trigger on. The row says what it does when the trigger is off instead of locking the field.
  { id: 'bullTrigger', kind: 'color', name: 'Bullish trigger', default: '#00bcd4', group: 'Singularity' },
  // A colour is a preference, not a plot: it stays editable while `Trigger` is off (T-1205), or the chosen colour could never be set before
  // turning the trigger on. The row says what it does when the trigger is off instead of locking the field.
  { id: 'bearTrigger', kind: 'color', name: 'Bearish trigger', default: '#ff0000', group: 'Singularity' },
  { id: 'alertTrigger', kind: 'bool', name: 'Trigger alert', default: false, group: 'Singularity', active: v => v['trigger'] !== false, inactive: 'Needs Trigger on.' },
];

const ohlc = (bar: Bar): ZoneOhlc => ({ o: bar[1], h: bar[2], l: bar[3], c: bar[4] });
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] as string : fallback;

/** The session a bar falls in, whichever variant: the variant decides which side it may carry (`:3571`, `:3630`). */
function sessionAt(sessions: readonly CycleSession[], t: number): CycleSession | null {
  for (const session of sessions) if (t >= session.from && t < session.to) return session;
  return null;
}

/** The side a session's window belongs to: A and M are the Pine's bullish windows, D and X its bearish ones (`:3571`, `:3630`). */
export function sideOfVariant(variant: CycleVariant): ZoneSide { return variant === 'A' || variant === 'M' ? 'bull' : 'bear'; }

export interface SingularityZone {
  readonly side: ZoneSide;
  /** The chart bar the condition fired on (its start). */
  readonly start: number;
  readonly end: number;
  readonly top: number;
  readonly bottom: number;
  /** The cycle session the Pine's window puts it in: A/M carry the bullish side, D/X the bearish one (`:3571`, `:3630`). */
  readonly session: CycleSession | null;
}

/**
 * The zones of the stretch, oldest first, one a chart bar whose condition holds. A bullish zone only exists inside an A/M session
 * (`:3571`) and a bearish one inside a D or X session (`:3630`): the window decides which condition is looked at. A forming bar is
 * never read: the last bar counts only once its period has ended.
 */
/**
 * The bars where a **live zone is retested**, which is what the Pine calls a trigger (`:2282-2286`, `:2325-2328`): it walks the boxes that
 * already exist and fires when the previous candle's low is inside the bullish box — or its high inside the bearish one — and this candle turns
 * (`close > open` over a down candle, and the mirror). Only inside a complement: A or M for the bull side, D or X for the bear (`:3010-3011`).
 * The condition that **creates** a zone is not a trigger and must not be read as one (T-1183).
 */
export function singularityTriggers(bars: readonly Bar[], zones: readonly SingularityZone[], now: number, zone: CycleZone = CYCLE_90_ZONE): { side: 'bull' | 'bear'; bar: Bar; zone: SingularityZone }[] {
  if (bars.length < 2 || !zones.length) return [];
  const barMs = bars[1]![0] - bars[0]![0];
  if (!(barMs > 0)) return [];
  const sessions = cycleSessions(bars, bars[0]![0], bars[bars.length - 1]![0] + barMs, now, zone);
  const out: { side: 'bull' | 'bear'; bar: Bar; zone: SingularityZone }[] = [];
  for (let index = 1; index < bars.length; index += 1) {
    const current = bars[index]!, prev = bars[index - 1]!;
    if (current[0] + barMs > now) break;
    const variant = sessionAt(sessions, current[0])?.variant;
    const bullHere = variant === 'A' || variant === 'M', bearHere = variant === 'D' || variant === 'X';
    for (const item of zones) {
      // The box has to exist by the candle whose low or high is being read: a zone is born on `current`'s own bar, never before it.
      if (item.end > prev[0]) continue;
      if (item.side === 'bull' && bullHere && prev[3] <= item.top && prev[3] >= item.bottom && current[4] > current[1] && prev[4] < prev[1]) {
        out.push({ side: 'bull', bar: current, zone: item });
      } else if (item.side === 'bear' && bearHere && prev[2] >= item.bottom && prev[2] <= item.top && current[4] < current[1] && prev[4] > prev[1]) {
        out.push({ side: 'bear', bar: current, zone: item });
      }
    }
  }
  return out;
}

export function singularityZones(bars: readonly Bar[], now: number, zone: CycleZone): SingularityZone[] {
  if (bars.length < 4) return [];
  const barMs = bars[1]![0] - bars[0]![0];
  if (!(barMs > 0)) return [];
  const sessions = cycleSessions(bars, bars[0]![0], bars[bars.length - 1]![0] + barMs, now, zone);
  const zones: SingularityZone[] = [];
  for (let index = 3; index < bars.length; index += 1) {
    const current = bars[index]!;
    if (current[0] + barMs > now) break; // the forming bar carries no zone
    const cur = ohlc(current), p1 = ohlc(bars[index - 1]!), p2 = ohlc(bars[index - 2]!), p3 = ohlc(bars[index - 3]!);
    const start = bars[index - 1]![0], end = current[0] + barMs;
    const session = sessionAt(sessions, current[0]);
    if (!session) continue;
    // Pine levels: bullish top low[1] over low[3] (`:3571`), bearish high[3] over high[1] (`:3632`), copied as they are.
    if (sideOfVariant(session.variant) === 'bull') {
      if (singularityBullishChart(cur, p1, p2, p3)) zones.push({ side: 'bull', start, end, top: p1.l, bottom: p3.l, session });
      continue;
    }
    if (singularityBearishChart(cur, p1, p2, p3)) zones.push({ side: 'bear', start, end, top: p3.h, bottom: p1.h, session });
  }
  return zones;
}

/**
 * Pine `_Delete_Present_Box_Bullish_Mitigated` / `_Bearish_` (`GF:901`, `:936`), as one rule: a zone is crossed when a **later**
 * confirmed close went under a bullish box's bottom (`precio = box.get_bottom(bx)`) or over a bearish box's top (`box.get_top(bx)`).
 * With `singularity_mitigated` off — the Pine's default — a crossed zone is deleted; with it on, nothing is deleted.
 */
export function zoneCrossed(zone: SingularityZone, bars: readonly Bar[]): boolean {
  for (const bar of bars) {
    if (bar[0] < zone.end) continue;
    if (zone.side === 'bull' ? bar[4] < zone.bottom : bar[4] > zone.top) return true;
  }
  return false;
}

/** The Pine's cap in 'Present' mode, per side: the newest `last` of each, the oldest dropped first (`GF:925-928`, `:959-962`). */
export function capZonesBySide(zones: readonly SingularityZone[], last: number): SingularityZone[] {
  const size = Math.max(1, Math.min(50, Math.round(last)));
  const kept = new Set<SingularityZone>();
  for (const side of ['bull', 'bear'] as const) for (const zone of zones.filter(item => item.side === side).slice(-size)) kept.add(zone);
  return zones.filter(zone => kept.has(zone));
}

export const SINGULARITY: StudyDef = {
  api: STUDY_API,
  id: 'singularity',
  name: 'Singularity',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 4) return null;
    const params = readInputs(INPUTS, ctx.params);
    // The windows are the Pine's zone (D-14, D-30): the page's zone never moves them, only writes their hours.
    const zone: CycleZone = CYCLE_90_ZONE;
    const bull = flag(params, 'bull'), bear = flag(params, 'bear');
    const found = singularityZones(series.bars, ctx.now, zone).filter(item => item.side === 'bull' ? bull : bear);
    // Mitigation first, the cap after, as the Pine runs them (`OEC:649-650` every bar, the trim on the last one).
    const survived = flag(params, 'mitigated') ? found : found.filter(item => !zoneCrossed(item, series.bars));
    const zones = text(params, 'mode', 'Present') === 'Historic' ? survived : capZonesBySide(survived, number(params, 'last', 5));
    // The trigger is a **retest** of a live zone (`OEC:2282-2286`), never the bar the zone was born on. Its bands go before the boxes so a box
    // covers its own; `mark_trigger` recolours the retested box, which is why the colour of a retested box is the trigger's (T-1183).
    const triggerPlots: Plot[] = [];
    const retested = new Set<SingularityZone>();
    if (flag(params, 'trigger')) {
      const barMs = series.bars.length > 1 ? series.bars[1]![0] - series.bars[0]![0] : 0;
      // A side switched off is not drawn at all: its zones already say so, and its trigger bands follow the same switch.
      for (const hit of singularityTriggers(series.bars, zones, ctx.now, zone).filter(item => item.side === 'bull' ? bull : bear)) {
        retested.add(hit.zone);
        if (hit.bar[0] < ctx.view.t0 || hit.bar[0] > ctx.view.t1) continue;
        const color = hit.side === 'bull' ? text(params, 'bullTrigger', '#00bcd4') : text(params, 'bearTrigger', '#ff0000');
        triggerPlots.push({ kind: 'bgcolor', t0: hit.bar[0], t1: hit.bar[0] + barMs, p0: hit.bar[3], p1: hit.bar[2], color, alpha: 0.5 });
      }
    }
    if (!zones.length) return triggerPlots.length ? { plots: triggerPlots } : null;
    const plots: Plot[] = [...triggerPlots], tags = [];
    // Same `limit_right` as `reverse-zone` (`GF:281-282`): in 'Right' the box is anchored at the port's own now, `timenow + bars * barMs`.
    // The Pine's bearish 'Right' box reads `rz_distancer` instead of `singularity_distancer` (`OEC:3632`); that cross-reference cannot be
    // reproduced with two separate pieces, so it is declared in the card and this piece uses its own distance.
    const barMs = series.bars.length > 1 ? series.bars[1]![0] - series.bars[0]![0] : 0;
    const now = ctx.replayAt ?? ctx.now;
    // The chart's last bar, which `Extend_Box` measures from (`bar_index + 8`): the boxes all stop at the same point (T-1187).
    const lastBar = series.bars[series.bars.length - 1]![0];
    const style = text(params, 'style', 'Future');
    const future = style === 'Future', right = style === 'Right';
    const anchorAt = now + Math.max(0, Math.round(number(params, 'anchor', 30) * barMs));
    const extendAt = now + Math.max(1, Math.round(number(params, 'extend', 160) * barMs));
    for (const item of zones) {
      // `mark_trigger` paints the retested box with the trigger's colour (`OEC:2289`, `:2332`), so a box that was retested says so.
      const color = retested.has(item)
        ? (item.side === 'bull' ? text(params, 'bullTrigger', '#00bcd4') : text(params, 'bearTrigger', '#ff0000'))
        : (item.side === 'bull' ? text(params, 'bullColor', '#73c3e1') : text(params, 'bearColor', '#ffc0b2'));
      // The Pine's own words, no session name (`OEC:3571`, `:3632`): `+S` / `-S`, and `+S Critical` / `-S Critical` when the bar is in the
      // complementary window — A for the bullish box and D for the bearish one (`time_critical_complement_D ? '-S Critical' : '-S'`).
      const critical = item.side === 'bull' ? item.session?.variant === 'A' : item.session?.variant === 'D';
      const name = `${item.side === 'bull' ? '+' : '-'}S${critical ? ' Critical' : ''}`;
      // 'Future' extends the box eight bars past the trigger on **both** sides (`_Extend_Box(_bullbox_singularity, 8)` /
      // `(_bearbox_singularity, 8)`, `OEC:3695-3697`); 'Right' anchors it at now, as the Pine does (`GF:281-282`).
      const t0 = right && barMs > 0 ? anchorAt : item.start;
      // `_Extend_Box(..., 8)` (`GF:632-637`, called at `:2240-2241`): **every** box ends at the last bar plus eight, not eight bars past
      // its own end — an old box would otherwise stop short of a new one (T-1187).
      const t1 = right && barMs > 0 ? extendAt : future && barMs > 0 ? lastBar + 8 * barMs : item.end;
      // `mark_trigger` (`OEC-Strategy:2135-2143`): a retested box is filled at 10 % (was 50 %), keeps the trigger's border and takes a
      // **dotted** border. The Pine also dims its text to 70; a label plot carries no alpha, so that one is declared, not faked (T-1187).
      plots.push(retested.has(item)
        ? { kind: 'box', t0, t1, p0: item.bottom, p1: item.top, color, alpha: 0.1, dash: [2, 3] }
        : { kind: 'box', t0, t1, p0: item.bottom, p1: item.top, color, alpha: 0.5 });
      tags.push({ key: `sg:${item.side}:${item.session?.id ?? 'none'}`, price: item.top, text: name, rank: 3.2, color });
    }
    return { plots, tags };
  },
};
