import { language, t } from '../i18n.ts';
import { sweepBands, sweepStylePaints, type SweepBar } from './sweep.ts';
import { LabelBoard, LABEL_GAP } from '../labels.ts';
import { price as fmtPrice } from '../format.ts';
import type { Palette } from '../theme.ts';
import type { View } from '../view.ts';
import { lineEnd, type KeyLine, type LevelWhat, type PeriodKind } from './levels.ts';
import { placeTags, type Band, type TagWish } from './tags.ts';
import type { KeyLevelSettings } from './settings.ts';
import type { PreviousLevel } from '../../indicators/previous-ohlc.ts';

/** Each line's short name as traders write it: PDH/PDL/PDC previous day high/low/close; PWH/PWL/PWC week; PMH/PML/PMC month. */
const CODES: Readonly<Record<PeriodKind, Readonly<Record<'high' | 'low' | 'close', string>>>> = {
  day: { high: t('PDH'), low: t('PDL'), close: t('PDC') },
  week: { high: t('PWH'), low: t('PWL'), close: t('PWC') },
  month: { high: t('PMH'), low: t('PML'), close: t('PMC') },
};

export function codeOf(line: Pick<KeyLine, 'period' | 'what' | 'prev'>): string {
  return CODES[line.period][line.what];
}

/** The period's dash: a day solid, a week dashed, a month dash-dot, as the indicator's `line_style` says. */
const DASH: Readonly<Record<PeriodKind, number[]>> = { day: [], week: [8, 4], month: [14, 4, 3, 4] };
/** The block's own line styles (`keylevels_style`, `OEC:132`) and `Period`: the product's addition, the dash each period already had (T-1186). */
const STYLE_DASH: Readonly<Record<'solid' | 'dashed' | 'dotted' | 'period', number[] | null>> = { solid: [], dashed: [8, 4], dotted: [3, 3], period: null };
/** The label's three sizes (`keylevels_text`, `:134`), in the pixels the labels are drawn at. */
const TEXT_PX: Readonly<Record<'Tiny' | 'Small' | 'Normal', number>> = { Tiny: 9, Small: 10, Normal: 12 };
/** Which tag and label wins a tie for room: the month's over the week's over the day's, and a previous high or low over a previous close. */
const PERIOD_RANK: Readonly<Record<PeriodKind, number>> = { month: 0, week: 1, day: 2 };
const WHAT_RANK = (what: LevelWhat): number => what === 'close' ? 1 : 0;
export const rankOf = (line: Pick<KeyLine, 'period' | 'what' | 'prev'>): number => PERIOD_RANK[line.period] * 2 + WHAT_RANK(line.what);

/**
 * A tag on the price axis; `older` for a level of an earlier period still running on (outlined, after the current ones). `color`: another
 * feature's tag placed with these (the VWAP's), in its own colour; the level colour when absent.
 */
export interface KeyTag extends TagWish { text: string; older: boolean; color?: string }
export const TAG_H = 14;
/** How far down the order a level of an earlier period still running on goes: after every line of the periods under way and just ended. */
const OLDER_RANK = 20;

/**
 * A level's name at the right end of its line, before it is drawn: what `paintLevels` collects and `paintLevelLabels` merges and places, so two
 * levels at one price are one label (`f_LevelMerge`, `GlobalFunctions:1277-1288`).
 */
export interface LabelWish { text: string; x: number; y: number; rank: number; alpha: number; color: string; fill?: boolean }

/** The hierarchy's own order: the coarser level first, as the axis tags (`rankOf`). `compact` is the block's `keylevels_compact`. */
export const mergeLabels = (wishes: readonly LabelWish[], compact: boolean): LabelWish[] => {
  const out: LabelWish[] = [];
  for (const wish of [...wishes].sort((a, b) => a.rank - b.rank)) {
    const same = compact && wish.y > 0 ? out.find(other => Math.abs(other.y - wish.y) < 1) : undefined;
    if (same) { same.text = `${same.text} / ${wish.text}`; same.fill = same.fill && wish.fill; }
    else out.push({ ...wish });
  }
  return out;
};

/** Draw the labels `paintLevels` collected, merged at one price; a filled one (`keylevels_fill_orderflow`) takes its colour's box. */
export function paintLevelLabels(ctx: CanvasRenderingContext2D, wishes: readonly LabelWish[], pw: number, ph: number, p: Palette, s: KeyLevelSettings, board: LabelBoard = new LabelBoard()): void {
  if (!wishes.length) return;
  ctx.save(); ctx.beginPath(); ctx.rect(0, 0, pw, ph); ctx.clip();
  ctx.font = `600 ${TEXT_PX[s.previous.text]}px ui-sans-serif, system-ui, sans-serif`; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
  for (const l of mergeLabels(wishes, s.previous.compact)) {
    const w = ctx.measureText(l.text).width + 8, box = { x0: l.x - w, x1: l.x, y0: l.y - 7, y1: l.y + 7 };
    if (l.y < 7 || l.y > ph - 7 || !board.claim(box)) continue;
    ctx.globalAlpha = l.alpha;
    ctx.fillStyle = l.fill ? l.color : p.panel; ctx.fillRect(box.x0, box.y0, w, 14);
    ctx.fillStyle = l.fill ? p.bg : l.color; ctx.fillText(l.text, l.x - 4, l.y);
  }
  ctx.restore(); ctx.globalAlpha = 1;
}

const dateFormats = new Map<string, Intl.DateTimeFormat>();
/** The day a period began, in its zone ("Oct 7"; a month as "Sep 2026"), to name a level that runs on past the period after it. */
export function periodDate(t: number, period: PeriodKind, zone: string): string {
  const key = `${language()}|${zone}|${period}`;
  let f = dateFormats.get(key);
  if (!f) { try { f = new Intl.DateTimeFormat(language(), period === 'month' ? { month: 'short', year: 'numeric', timeZone: zone } : { month: 'short', day: 'numeric', timeZone: zone }); } catch { f = new Intl.DateTimeFormat(language(), { month: 'short', day: 'numeric', timeZone: 'UTC' }); } dateFormats.set(key, f); }
  return f.format(new Date(t));
}

/**
 * One level to paint, whatever its route (T-1198): the key levels' own day/week/month lines and the four intraday frames of the previous-OHLC
 * block reach the same painter in this shape, so **every** input of the block —style, width, text, short, price, labels, dates, tags, opacity,
 * the orderflow colours and their fill, `Right` with anchor and extend, `Compact`— is applied once and cannot be lost on one of the two paths.
 */
export interface DrawnRow {
  code: string;
  price: number;
  from: number;
  to: number;
  /** For a level of an earlier period not traded through: the first later bar that reached it, or null (runs on). */
  reached?: number | null;
  /** When the period whose level it is began: the date the `Dates` switch prints. */
  of: number;
  /** The day/week/month a key level belongs to; null for an intraday frame, which says "Previous" alone when `Short` is off. */
  group: PeriodKind | null;
  period: PeriodKind;
  /** The orderflow side of the period (`biasState`, the HTF candles' and trend-bias's own function): what `Orderflow` colours with. */
  bias: 'bull' | 'bear' | 'neutral';
  /** The level's own colour, used when the orderflow colour is off. */
  color: string;
  rank: number;
  window: string;
  older: boolean;
  /** The day's high and low are drawn half again as thick as its close, as they always were. */
  bold: boolean;
  alphaFactor: number;
  /** A frame's axis tag keeps its own colour; a key line's takes the palette's. */
  ownTagColor: boolean;
  /** Which of the three levels it is: the close runs on, the high and the low stop where price reaches them (T-1222). */
  what: 'high' | 'low' | 'close';
  /** The first bar price traded through it, or null while untouched (T-1222). */
  touched: number | null;
  /** The newest completed period's close is never dimmed (T-1222). */
  newest: boolean;
}

/** The key levels' own lines as drawn rows. `bias` is the orderflow side `keyLines` already worked out; the colour is the palette's tone of it. */
export function keyRows(lines: readonly KeyLine[], p: Palette, now: number): DrawnRow[] {
  return lines.map((l): DrawnRow => {
    const older = l.reached !== undefined && l.to <= now;
    return {
      code: codeOf(l), price: l.price, from: l.from, to: l.to, ...(l.reached !== undefined ? { reached: l.reached } : {}),
      of: l.of, group: l.period, period: l.period, bias: l.bias ?? 'neutral',
      color: l.bias === 'bull' ? p.bid : l.bias === 'bear' ? p.ask : l.bias === 'neutral' ? p.muted : p.level,
      rank: rankOf(l) + (older ? OLDER_RANK : 0), window: l.window, older,
      bold: (l.what === 'high' || l.what === 'low') && l.prev, alphaFactor: l.what === 'close' ? 0.9 : 1, ownTagColor: false,
      what: l.what, touched: l.touched ?? null, newest: l.newest === true,
    };
  });
}

/** The previous-OHLC frames as drawn rows, with the same shape as the key levels' lines. */
export function frameRows(levels: readonly PreviousLevel[]): DrawnRow[] {
  return levels.map((level): DrawnRow => {
    const period: PeriodKind = level.frame === 'pw' ? 'week' : level.frame === 'pm' ? 'month' : 'day';
    return {
      code: level.code, price: level.price, from: level.from, to: level.to, of: level.from, group: null, period,
      bias: level.bias ?? 'neutral', color: level.color, rank: FRAME_RANK[level.frame] ?? 8, window: `${level.code}|${level.from}`,
      older: false, bold: false, alphaFactor: 1, ownTagColor: true,
      what: level.what ?? 'close', touched: level.touched ?? null, newest: level.newest === true,
    };
  });
}

/** A `#rrggbb` colour with an alpha, for a gradient stop: the canvas takes `#rrggbbaa`. */
const withAlpha = (hex: string, alpha: number): string => {
  const clamped = Math.max(0, Math.min(1, alpha));
  const a = Math.round(clamped * 255).toString(16).padStart(2, '0');
  return `${hex.slice(0, 7)}${a}`;
};

export interface PaintOptions {
  now: number;
  zone: string;
  /** The chart's bar size: `Right` places the level this many bars out (`keylevels_distancea/r`, `OEC:129-131`). */
  barMs: number;
  /**
   * T-1246: las velas de HTF 1 y el cierre previo de HTF 2 contra el que se barre. Sin esto no se pinta ni área ni marca; el pintor sólo
   * dibuja lo que `sweepBands` ya resolvió.
   */
  sweep?: { readonly bars: readonly SweepBar[]; readonly level: number } | null;
}

/**
 * Where one level's line begins and ends on the canvas, by the Pine's own rules (`Previous_OHLC:990`, `OEC:1417-1423`): `Right` closes every line at
 * the plot's edge (D-40), the newest close runs on to that edge, an older one stops at the end of its own period, and a high or a low runs to the edge
 * until price touches it and stops at the touch. `Compact` needs it before anything is drawn: at one price the line that reaches further wins.
 */
function endsOf(row: DrawnRow, v: View, pw: number, s: KeyLevelSettings, o: PaintOptions): { x0: number; x1: number; rightEdge: number } {
  const right = s.previous.displaystyle === 'Right' && o.barMs > 0;
  const span = Math.max(1, v.t1 - v.t0), barsPx = (o.barMs / span) * pw;
  const lengthPx = Math.min(pw, Math.max(1, Math.abs(s.previous.extend - s.previous.anchor) * barsPx));
  const x0 = right ? Math.max(-4, pw - lengthPx) : Math.max(-4, v.xOf(row.from, pw));
  let x1 = right ? pw : Math.min(pw + 4, v.xOf(row.to, pw));
  if (!right) {
    // A high or a low is ended by the Pine at `_edge`, and the touch only cuts it short (`_x2c`, `OEC:1423`: `_hit ? _tch : _edge`).
    if (row.what !== 'close') x1 = row.touched === null ? pw + 4 : Math.min(pw + 4, v.xOf(row.touched, pw));
    // The newest close is the one that runs on (`_k == 0 ? _edge`, `OEC:1423`).
    else if (row.newest) x1 = pw + 4;
  }
  return { x0, x1, rightEdge: right ? pw + 4 : x1 };
}

/**
 * The rows `Compact` keeps: one line per price (`Previous_OHLC:1016-1046`). The winner is the wider period — the Pine's `_rnew > _rold`, its slot 21
 * being the month's — and, at equal width, the one reaching further right (`_x2c > _xhold`). null when the switch is off.
 */
function compactWinners(rows: readonly DrawnRow[], v: View, pw: number, s: KeyLevelSettings, o: PaintOptions): Set<DrawnRow> | null {
  if (!s.previous.compact) return null;
  const rangeOf = (row: DrawnRow): number => row.group === 'month' ? 3 : row.group === 'week' ? 2 : row.group === 'day' ? 1 : 0;
  const atPrice = new Map<number, { row: DrawnRow; reach: number }>(), winners = new Set<DrawnRow>();
  for (const row of rows) {
    if (!Number.isFinite(row.price)) continue;
    const { x1 } = endsOf(row, v, pw, s, o), seen = atPrice.get(row.price);
    if (!seen) { atPrice.set(row.price, { row, reach: x1 }); winners.add(row); continue; }
    if (rangeOf(row) > rangeOf(seen.row) || (rangeOf(row) === rangeOf(seen.row) && x1 > seen.reach)) {
      winners.delete(seen.row); atPrice.set(row.price, { row, reach: x1 }); winners.add(row);
    }
  }
  return winners;
}

/**
 * Draw every level of the piece with one set of rules, returning the tags wanted on the price axis. `keylevels_displaystyle == 'Right'` places
 * **every** level from `now + anchor` bars to `now + extend` bars, as the Pine's `Previous_OHLC` does for each call (`:1293-1295`); `Future`
 * keeps each level over its own period, an untouched one running on dotted. The orderflow colour (`keylevels_compact_orderflow` with the two
 * colours, `:138-141`) paints the line and, with `Fill`, the label's box.
 */
export function paintLevels(ctx: CanvasRenderingContext2D, rows: readonly DrawnRow[], v: View, pw: number, ph: number, p: Palette, s: KeyLevelSettings, o: PaintOptions, board: LabelBoard = new LabelBoard(), batch: LabelWish[] = []): KeyTag[] {
  const tags: KeyTag[] = [];
  if (!rows.length) return tags;
  // One rule for every level (T-1198): the key levels' switches and the block's act together, so no line can answer to a different set.
  const labelsOn = s.labels && s.previous.labels, pricesOn = s.previous.prices, orderflowOn = s.previous.compactOrderflow;
  const right = s.previous.displaystyle === 'Right' && o.barMs > 0;
  const halo = p.dark ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.75)';
  const levelAlpha = (s.opacity ?? 100) / 100;
  const stroke = (x0: number, x1: number, y: number, dash: number[], width: number, color: string): void => {
    if (x1 <= x0) return;
    ctx.setLineDash(dash);
    ctx.strokeStyle = halo; ctx.lineWidth = width + 2; ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke();
    ctx.strokeStyle = color; ctx.lineWidth = width; ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke();
  };
  ctx.save(); ctx.beginPath(); ctx.rect(0, 0, pw, ph); ctx.clip();
  // `Compact` keeps one line per price, decided before drawing (`Previous_OHLC:1016-1046`); off, every row draws its own (T-1302).
  const winners = compactWinners(rows, v, pw, s, o);
  for (const row of rows) {
    // A row whose line another one takes still gives its code to the label: the Pine deletes the line and merges both names into the one label it
    // keeps (`f_LevelMerge`, `:1057`), which is why two levels at one price read `PDC / P4H-C` and not one of the two (T-1302).
    const line = !winners || winners.has(row);
    // A level whose price is not a number is not drawn (T-1199): one bad bar must not take the whole paint, and the key levels with it, down.
    if (!Number.isFinite(row.price) || !Number.isFinite(row.from) || !Number.isFinite(row.to)) continue;
    const y = Math.round(v.yOf(row.price, ph)) + 0.5; if (y < -2 || y > ph + 2) continue;
    // `Right` (`:1293-1295`) runs every level from `timenow + anchor` to `timenow + extend`; `Future` keeps its own period. The Pine's two ends are
    // both in the future and the chart reserves only an eighth of its span past now, so `Right` keeps the segment's **length** and closes it at the
    // plot's edge, which is where the Pine's line would be read (T-1200, D-40). The rules themselves live in `endsOf`, so the compact pass and this
    // one cannot disagree.
    const { x0, x1, rightEdge } = endsOf(row, v, pw, s, o);
    if (Math.max(x1, rightEdge) < 0 || x0 > pw) continue;
    // The colour is the one of the period's **HTF candle** (T-1222): the side `biasState` gave, in the same three colours the candles use, frozen
    // with the period as the Pine freezes it (`OEC:1371`, read back at `:1427-1430`). With the orderflow switch off the row keeps its own colour.
    const color = orderflowOn
      ? row.bias === 'bull' ? s.previous.bullColor : row.bias === 'bear' ? s.previous.bearColor : p.muted
      : row.color;
    const dash = STYLE_DASH[s.previous.style] ?? DASH[row.period];
    // The Pine draws every line at `_keylevels_width` (`:976`, `:1004`); the day's high and low were half again as thick here, which is not in the
    // indicator and read as a different line for a level beside another (T-1302).
    const width = s.previous.width;
    // Only a line price has traded through, and that is not the newest one, is dimmed — to 30 % of its opacity (`color.new(_base, 70)`, `:1433-1435`).
    const dim = row.touched !== null && !row.newest;
    ctx.globalAlpha = row.alphaFactor * levelAlpha * (dim ? 0.3 : 1);
    if (line) stroke(x0, x1, y, dash, width, color);
    // `keylevels_globalshort` (`:135`): the code alone, or the period named before it.
    const named = s.previous.short ? row.code : row.group
      ? `${row.group === 'day' ? t('Previous day') : row.group === 'week' ? t('Previous week') : t('Previous month')} ${row.code}`
      : `${t('Previous')} ${row.code}`;
    // The Pine prints `' $'` before the amount with `format.mintick` (`:1000`), and the newest's price is the live one: `Previous_OHLC_Level`
    // (`:1067`) passes its price twice, so the stored price of the newest row is that value.
    const value = pricesOn ? ` $${fmtPrice(row.price)}` : '';
    // The Pine prints the date on a level that ran past its period; here `Dates` asks for it on every one.
    const date = row.older || s.dates ? `${LABEL_GAP}${periodDate(row.of, row.period, o.zone)}` : '';
    const text = `${named}${value}${date}`;
    if (labelsOn && rightEdge - Math.max(0, x0) > 60) {
      batch.push({ text, x: Math.min(pw - 2, rightEdge - 2), y, rank: row.rank, alpha: ctx.globalAlpha, color, fill: s.previous.fillOrderflow && orderflowOn && row.bias !== 'neutral' });
    }
    // One tag a price: only the line that was kept asks for room on the axis.
    if (s.tags && line && rightEdge >= pw - 1) tags.push({ key: `${row.code}|${row.window}`, y, rank: row.rank, text: row.code, older: row.older, ...(row.ownTagColor ? { color } : {}) });
  }
  // El barrido de HTF 2 (T-1246): el área entre el nivel y la mecha de las barras que lo barren, y una marca por barrido nuevo. Va aquí, con
  // las líneas ya puestas, porque el relleno es del nivel y su color es el de su lado (`OEC:1692-1697`, `:1739`).
  const sweep = o.sweep;
  if (sweep && sweep.bars.length && o.barMs > 0) {
    const paints = sweepStylePaints(s.previous.sweepStyle);
    const { bands, marks } = sweepBands(sweep.bars, sweep.level, o.barMs);
    if (paints.fill) {
      for (const band of bands) {
        const x0 = Math.max(-4, v.xOf(band.t0, pw)), x1 = Math.min(pw + 4, v.xOf(band.t1, pw));
        if (x1 <= x0) continue;
        const yTop = v.yOf(band.top, ph), yBottom = v.yOf(band.bottom, ph);
        if (!Number.isFinite(yTop) || !Number.isFinite(yBottom)) continue;
        // El Pine no rellena plano: `fill()` lleva **dos** colores (`:1730-1731`), el de arriba y el de abajo, y son distintos — con barrido
        // los dos van a transparencia 30, y sin él el de arriba va a 100 (invisible) y el de abajo al color entero (`:1696-1697`). Eso es un
        // degradado vertical, no un alpha: el área se apaga hacia el nivel y se enciende hacia la mecha.
        const swept = band.alpha < 100;
        const color = band.side === 'bull' ? s.previous.bullColor : s.previous.bearColor;
        const gradient = ctx.createLinearGradient(0, yTop, 0, yBottom);
        gradient.addColorStop(0, withAlpha(color, (swept ? 0.7 : 0) * levelAlpha));
        gradient.addColorStop(1, withAlpha(color, (swept ? 0.7 : 1) * levelAlpha));
        ctx.globalAlpha = 1;
        ctx.fillStyle = gradient;
        ctx.fillRect(x0, Math.min(yTop, yBottom), x1 - x0, Math.abs(yBottom - yTop));
      }
    }
    if (paints.markers) {
      for (const mark of marks) {
        const x = v.xOf(mark.t, pw), y = v.yOf(mark.price, ph);
        if (!Number.isFinite(y) || x + 4 < 0 || x - 4 > pw) continue;
        const half = Math.max(2, o.barMs > 0 ? Math.min(6, (v.xOf(mark.t + o.barMs, pw) - x) / 2) : 3);
        ctx.globalAlpha = levelAlpha;
        ctx.fillStyle = mark.side === 'bull' ? s.previous.bullColor : s.previous.bearColor;
        ctx.fillRect(x - half, y - 2, half * 2, 4);
      }
    }
    ctx.globalAlpha = 1;
  }
  ctx.setLineDash([]);
  ctx.restore(); ctx.globalAlpha = 1;
  return tags;
}

/** The tags kept on the price axis: clear of each other and of `blocked` (the live price's tag), each at its own price. */
export const placeKeyTags = (tags: readonly KeyTag[], blocked: readonly Band[], ph: number): KeyTag[] => tags.length ? placeTags(tags, blocked, TAG_H, ph) : [];

/** Whether a price label on the axis at `y` would sit under one of the tags (it is then left out, so no half-covered number shows). */
export const underTag = (tags: readonly KeyTag[], y: number): boolean => tags.some(k => Math.abs(k.y - y) < TAG_H / 2 + 6);

/** Draw the tags `placeKeyTags` kept, in their colour (outlined for a level of an earlier period). */
export function paintKeyTags(ctx: CanvasRenderingContext2D, tags: readonly KeyTag[], axisX: number, axisW: number, p: Palette): void {
  if (!tags.length) return;
  ctx.save();
  ctx.font = '600 10px ui-sans-serif, system-ui, sans-serif'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
  for (const tag of tags) {
    const y = Math.round(tag.y), color = tag.color ?? p.level;
    if (tag.older) { // outlined: a level of an earlier period still running on
      ctx.fillStyle = p.panel; ctx.fillRect(axisX + 1, y - TAG_H / 2, axisW - 1, TAG_H);
      ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.strokeRect(axisX + 1.5, y - TAG_H / 2 + 0.5, axisW - 2, TAG_H - 1);
      ctx.fillStyle = color;
    } else { ctx.fillStyle = color; ctx.fillRect(axisX + 1, y - TAG_H / 2, axisW - 1, TAG_H); ctx.fillStyle = p.bg; }
    ctx.fillText(tag.text, axisX + 6, y + 0.5);
  }
  ctx.restore();
}

/** Which frame wins a tie for room on the label board: the coarser period over the finer one, as the key levels' month over its week. */
const FRAME_RANK: Readonly<Record<string, number>> = { pm: 0, pw: 1, pd: 2, p4h: 3, p1h: 4, p15m: 5, p5m: 6, p1m: 7 };
